insert into public.exams(slug,title,source,year) values ('cfc-2026-2','CFC 2026.2 — Exame de Suficiência — Contador — Tipo 1','cfc','2026') on conflict(slug) do update set title=excluded.title,source=excluded.source,year=excluded.year;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,1,'Língua Portuguesa','Nas frases abaixo foram feitas substituições, mantendo-se o mesmo sentido original. Assinale a opção em que a modificação não está adequada por alterar esse sentido original.',null,'{"original": ["/cfc-2026-2/q1-1.png"]}','["A música é a alma da geometria /A música é a essência da geometria.", "Somente por meio do amor o homem pode ser liberado de si mesmo / Por meio do amor somente o homem pode ser liberado de si mesmo.", "O amor é a capacidade de perceber o semelhante no dessemelhante / O amor é a capacidade de percepção do semelhante no dessemelhante.", "Todas as paixões nos fazem cometer erros / Todas as paixões fazem que cometamos erros."]'::jsonb,'B',null from public.exams where slug='cfc-2026-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,2,'Língua Portuguesa','Assinale a única frase abaixo que se mostra gramaticalmente correta.',null,'{"original": ["/cfc-2026-2/q2-1.png"]}','["A polícia interviu na briga entre as torcidas, após o jogo.", "Compras à crédito podem trazer problemas futuros.", "Haviam muitos carros abandonados ne estrada por causa dos desabamentos.", "Para mim, trabalhar é uma atividade prazerosa."]'::jsonb,'D',null from public.exams where slug='cfc-2026-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,3,'Matemática Financeira e Estatística','Um empréstimo no valor de R$ 500.000,00 será quitado segundo o Sistema de Amortização Constante (SAC). O contrato estabelece um prazo de 40 meses para a quitação, com parcelas mensais, postecipadas e juros fixos de 2% ao mês, incidentes sobre o saldo devedor remanescente do período imediatamente anterior. Sabe-se que uma das parcelas mensais terá valor de R$ 18.250,00. Desconsiderando-se quaisquer encargos adicionais, tais como IOF, seguros, moras e taxas, é correto concluir que esse é o valor do',null,'{"original": ["/cfc-2026-2/q3-1.png"]}','["17º pagamento.", "18º pagamento.", "19º pagamento.", "20º pagamento."]'::jsonb,'B',null from public.exams where slug='cfc-2026-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,4,'Matemática Financeira e Estatística','Ao encerrar o exercício social, o contador de uma empresa identificou um excedente temporário de caixa no valor de R$ 25.000,00. A diretoria autorizou a aplicação desse valor em um investimento financeiro remunerado à taxa de 8% ao ano, sob o regime de juros compostos. Se o recurso permanecer aplicado por 2 anos, sem aportes ou resgates intermediários, o montante acumulado ao final do período de aplicação será de:',null,'{"original": ["/cfc-2026-2/q4-1.png"]}','["R$ 26.000,00.", "R$ 27.000,00.", "R$ 28.160,00.", "R$ 29.160,00."]'::jsonb,'D',null from public.exams where slug='cfc-2026-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,5,'Ciências Contábeis','Em observância às formalidades constitucionais e legais aplicáveis à espécie, a autarquia Alfa publicou edital de licitação visando à celebração de futuro contrato administrativo. Busca-se, assim, a prestação de serviços públicos de forma descentralizada e especializada, em atendimento ao interesse público primário. Nesse cenário, considerando as disposições da Constituição Federal e o entendimento doutrinário dominante, é correto afirmar que a autarquia Alfa, por se tratar de uma pessoa jurídica de direito',null,'{"original": ["/cfc-2026-2/q5-1.png"]}','["privado integrante da Administração Direta, teve a sua criação autorizada por lei específica.", "público integrante da Administração Direta, teve a sua criação autorizada por lei específica.", "público integrante da Administração Indireta, foi criada por lei específica.", "privado integrante da Administração Indireta, foi criada por lei específica."]'::jsonb,'C',null from public.exams where slug='cfc-2026-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,6,'Ciências Contábeis','Após a observância do contraditório e da ampla defesa, como consectários do devido processo legal, a autoridade pública competente, no âmbito da autarquia Alfa, editou ato administrativo punitivo em detrimento de Lucas, servidor público estatutário, a ele aplicando a sanção administrativa de suspensão, em razão de infração funcional outrora praticada. Nesse cenário, considerando o entendimento doutrinário dominante, é correto afirmar que a infração funcional praticada por Lucas é',null,'{"original": ["/cfc-2026-2/q6-1.png"]}','["a finalidade do ato administrativo punitivo.", "o motivo do ato administrativo punitivo.", "o objeto do ato administrativo punitivo.", "o móvel do ato administrativo punitivo."]'::jsonb,'B',null from public.exams where slug='cfc-2026-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,7,'Ciências Contábeis','Ao analisar o teor da Constituição Federal, João, estudante, constatou que determinado princípio foi nela incluído por meio da Emenda Constitucional nº 19/1998, com o objetivo de substituir a Administração Pública burocrática pela Administração Pública gerencial. A ideia por trás desse princípio está intimamente relacionada com a necessidade de efetivação célere das finalidades públicas elencadas no ordenamento jurídico. Nesse cenário, considerando as disposições da Constituição Federal e o entendimento doutrinário dominante, é correto afirmar que se está fazendo referência ao princípio da',null,'{"original": ["/cfc-2026-2/q7-1.png"]}','["impessoalidade.", "moralidade.", "legalidade.", "eficiência."]'::jsonb,'D',null from public.exams where slug='cfc-2026-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,8,'Ciências Contábeis','A empresa Horizonte Ltda. enfrenta dificuldades financeiras e seus gestores solicitam ao contador que elabore relatórios financeiros para fins gerais “menos detalhados” para evitar questionamentos de credores e investidores. Considerando o papel da Contabilidade na sociedade e as disposições da NBC PG 01 – CÓDIGO DE ÉTICA PROFISSIONAL DO CONTADOR e da NBC PG 100 (R1) – CUMPRIMENTO DO CÓDIGO, DOS PRINCÍPIOS FUNDAMENTAIS E DA ESTRUTURA CONCEITUAL, a atuação adequada do profissional deve refletir o princípio de que a Contabilidade',null,'{"original": ["/cfc-2026-2/q8-1.png"]}','["serve exclusivamente como instrumento interno de controle gerencial.", "atende prioritariamente aos interesses dos administradores da entidade, o que gera a necessidade de se balancear função social com interesses financeiros.", "deve adaptar o nível de transparência das informações à conveniência da administração.", "tem a função social de produzir informações úteis, fidedignas e transparentes para os diversos usuários, preservando o interesse público e a confiança na profissão contábil."]'::jsonb,'D',null from public.exams where slug='cfc-2026-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,9,'Ciências Contábeis','Durante procedimento de fiscalização do CRC, verificou-se que um contador responsável técnico delegava integralmente a execução de serviços contábeis a terceiros não registrados, assinando posteriormente as demonstrações sem revisão técnica adequada. O contador alegava que a responsabilidade era apenas contratual perante o cliente. Considerando a Resolução CFC nº 1.612/2021 – REGULAMENTO GERAL DOS CONSELHOS DE CONTABILIDADE, a NBC PG 01 – CÓDIGO DE ÉTICA PROFISSIONAL DO CONTADOR e a NBC PG 100 (R1) – CUMPRIMENTO DO CÓDIGO, PRINCÍPIOS FUNDAMENTAIS E DA ESTRUTURA CONCEITUAL, a conduta profissional adequada reconhece que a responsabilidade técnica é',null,'{"original": ["/cfc-2026-2/q9-1.png"]}','["pessoal e indelegável, limitada ao vínculo contratual firmado com o cliente, exigindo supervisão efetiva, observância das normas profissionais e cooperação com a fiscalização para preservar o interesse público.", "pessoal e delegável, exigindo supervisão seletiva, observância das normas profissionais e alinhamento automático com a fiscalização na preservação dos interesses particulares.", "impessoal e delegável, exigindo supervisão seletiva, inobservância das normas profissionais e embate com a fiscalização a respeito do interesse público.", "pessoal e indelegável, exigindo supervisão efetiva, observância das normas profissionais e cooperação com a fiscalização para preservar o interesse público."]'::jsonb,'D',null from public.exams where slug='cfc-2026-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,10,'Ciências Contábeis','O contador Marcos atua como Perito Contábil inscrito no CNPC. Em um ano-calendário, cumpriu 35 pontos de Educação Profissional Continuada (EPC), sendo 10 na diretriz de aquisição de conhecimento. Acreditando estar regular, inseriu seus comprovantes no sistema Web EPC do Conselho Federal de Contabilidade, no dia 20 de fevereiro do exercício subsequente. Nesse caso, com base na NBC PG 12 (R5) – EDUCAÇÃO PROFISSIONAL CONTINUADA, avalie se cada afirmativa a seguir é verdadeira (V) ou falsa (F). ( ) A submissão à Educação Profissional Continuada é facultativa para Marcos, pois a obrigatoriedade normativa restringe-se aos auditores independentes e responsáveis técnicos. ( ) A pontuação alcançada por Marcos foi insuficiente, uma vez que a norma exige, no mínimo, 40 pontos anuais, sendo obrigatoriamente 12 pontos em aquisição de conhecimento. ( ) O envio da comprovação documental no sistema Web EPC foi intempestivo, visto que o prazo máximo determinado pela regulamentação é até 31 de janeiro do exercício subsequente. As afirmativas são, respectivamente,',null,'{"original": ["/cfc-2026-2/q10-1.png"]}','["F – V – V.", "V – F – F.", "F – F – V.", "V – V – F."]'::jsonb,'A',null from public.exams where slug='cfc-2026-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,11,'Ciências Contábeis','Em março de 2026, uma sociedade empresária publicou as suas demonstrações contábeis referentes a 31/12/2025. De acordo com a NBC TG ESTRUTURA CONCEITUAL – ESTRUTURA CONCEITUAL PARA RELATÓRIO FINANCEIRO, as demonstrações contábeis são elaboradas para um período de tempo específico (período de relatório), para ajudar os usuários a identificar e avaliar mudanças e tendências e também',null,'{"original": ["/cfc-2026-2/q11-1.png"]}','["calculam os principais indicadores de análise contábil.", "apresentam projeções para, pelo menos, o exercício seguinte.", "reproduzem as normas contábeis relacionadas a cada ponto apresentado.", "fornecem informações comparativas de, pelo menos, um período de relatório anterior."]'::jsonb,'D',null from public.exams where slug='cfc-2026-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,12,'Ciências Contábeis','Com base nos conceitos de ativos, passivos, receitas e despesas e dos critérios necessários para reconhecimento apresentados na NBC TG ESTRUTURA CONCEITUAL, assinale a afirmativa correta.',null,'{"original": ["/cfc-2026-2/q12-1.png"]}','["A receita deve ser reconhecida quando o cliente realiza o pedido para a realização de um determinado serviço, com contrapartida em Contas a Receber de Clientes.", "A distribuição de dividendos deve ser reconhecida como despesa financeira no resultado, em contrapartida ao passivo ou caixa.", "O aumento de capital gera o reconhecimento de receitas em contrapartida ao registro em caixa.", "O custo das mercadorias vendidas deve ser reconhecido quando ocorre a transferência de controle das mercadorias ao cliente, com a baixa dos estoques no ativo."]'::jsonb,'D',null from public.exams where slug='cfc-2026-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,13,'Ciências Contábeis','Uma companhia S.A. realizou recentemente sua oferta pública inicial de ações (IPO) e passou a negociar seus papéis em Bolsa de Valores. Em uma reunião do conselho de administração, o diretor de relações com investidores destacou a importância do relatório financeiro para fins gerais, afirmando que ele deve atender às necessidades informacionais dos diversos usuários externos da companhia. Durante a reunião, foram apresentadas algumas afirmações sobre o objetivo do relatório financeiro para fins gerais. Considerando-se os preceitos da NBC TG ESTRUTURA CONCEITUAL, é correto afirmar que',null,'{"original": ["/cfc-2026-2/q13-1.png"]}','["o relatório financeiro para fins gerais destina-se a apresentar o valor de mercado da entidade que reporta.", "a administração da companhia depende das informações do relatório financeiro para fins gerais para basear suas decisões estratégicas.", "o relatório financeiro para fins gerais fornece todas as informações de que necessitam investidores, credores por empréstimos e administradores da companhia para a tomada de decisões.", "o objetivo do relatório financeiro para fins gerais é fornecer informações úteis a investidores, credores por empréstimos e outros credores, existentes e potenciais, para decisões sobre o fornecimento de recursos à entidade."]'::jsonb,'D',null from public.exams where slug='cfc-2026-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,14,'Ciências Contábeis','Uma empresa S.A. tem como objeto a lavra, o processamento, o comércio e o transporte de petróleo proveniente de poço. Após o encerramento do exercício social de 2025, em 31/12/2025, e antes da data de autorização para emissão das demonstrações contábeis, uma plataforma de petróleo da empresa pegou fogo, gerando danos significativos ao ativo imobilizado. Considerando-se as informações apresentadas e os preceitos da NBC TG 24 (R2) – EVENTO SUBSEQUENTE, o incêndio',null,'{"original": ["/cfc-2026-2/q14-1.png"]}','["deve ser desconsiderado como um evento subsequente, pois ocorreu fora do período contábil de 2025.", "deve ser desconsiderado nas demonstrações contábeis, pois ainda não houve baixa da plataforma incendiada.", "é um evento subsequente que representa condição surgida após a data-base, devendo ser divulgado em nota explicativa.", "é um evento subsequente que exige ajuste nas demonstrações contábeis, pois evidencia uma condição existente na data- base."]'::jsonb,'C',null from public.exams where slug='cfc-2026-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,15,'Ciências Contábeis','A empresa Cargas ABC S.A. possui em seu Ativo Imobilizado um veículo utilizado para entregas. Ao final do exercício de 2025, a empresa realizou o teste de recuperabilidade (impairment) para esse Ativo. O contador da empresa levantou as seguintes informações: • Valor Contábil (após depreciação): R$ 150.000,00. • Valor Justo Líquido de despesas de venda: R$ 130.000,00. • Valor em uso: R$ 145.000,00. Com base nas disposições da NBC TG 01 (R4) – REDUÇÃO AO VALOR RECUPERÁVEL DE ATIVOS, o procedimento correto a ser adotado pela empresa é',null,'{"original": ["/cfc-2026-2/q15-1.png"]}','["reconhecer uma perda por desvalorização no valor de R$ 20.000,00, pois o valor de venda é o menor dentre os valores apresentados.", "não reconhecer nenhuma perda, pois o valor recuperável, de R$ 145.000,00, é maior do que o valor de venda.", "reconhecer uma perda por desvalorização no valor de R$ 5.000,00, para ajustar o valor contábil ao valor recuperável.", "ajustar o valor do ativo para R$ 130.000,00, em observância ao princípio da prudência."]'::jsonb,'C',null from public.exams where slug='cfc-2026-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,16,'Ciências Contábeis','A Indústria Metalúrgica Aço S.A. adquiriu uma nova máquina para sua linha de produção. Durante o processo de aquisição e instalação, a empresa incorreu nos seguintes gastos: • Preço de compra da máquina: R$ 200.000,00. • Gastos com frete e seguro para transporte até a fábrica: R$ 10.000,00. • Gastos com a preparação do local e fundação para instalação da máquina: R$ 15.000,00. • Treinamento dos funcionários para operar a nova máquina: R$ 5.000,00. • Gastos com testes para verificar se o equipamento está funcionando adequadamente: R$ 3.000,00. Com base nas disposições da NBC TG 27 (R4) – ATIVO IMOBILIZADO, o valor total que deve ser reconhecido inicialmente no Ativo da empresa referente a essa máquina é de',null,'{"original": ["/cfc-2026-2/q16-1.png"]}','["R$ 228.000,00.", "R$ 233.000,00.", "R$ 200.000,00.", "R$ 210.000,00."]'::jsonb,'A',null from public.exams where slug='cfc-2026-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,17,'Ciências Contábeis','Uma empresa adquiriu uma marca com vida útil considerada indefinida, um software com vida útil definida e máquinas industriais. Considerando o que estabelecem a NBC TG 01 (R4) – REDUÇÃO AO VALOR RECUPERÁVEL DE ATIVOS, a NBC TG 04 (R4) – ATIVO INTANGÍVEL e a NBC TG 27 (R4) – ATIVO IMOBILIZADO, assinale a opção que apresenta o tratamento contábil correto para o caso.',null,'{"original": ["/cfc-2026-2/q17-1.png"]}','["A empresa inicia a amortização dos intangíveis apenas quando obtém a propriedade legal, mesmo que já esteja utilizando esses ativos.", "A empresa amortiza a marca de vida útil indefinida a uma taxa anual fixa de 10%, por não ser possível estimar sua vida útil econômica.", "A empresa não amortiza a marca de vida útil indefinida, mas realiza anualmente o teste de redução ao valor recuperável desse ativo.", "A empresa utiliza as taxas de depreciação definidas pela legislação fiscal para registrar a depreciação das máquinas nas demonstrações contábeis societárias."]'::jsonb,'C',null from public.exams where slug='cfc-2026-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,18,'Ciências Contábeis','A Sociedade Empresária “A” adquiriu mercadorias para revenda à vista pelo valor bruto de R$ 100.000,00, indicado na nota fiscal do fornecedor. Nessa operação, considere as seguintes informações para a empresa compradora: ICMS (imposto recuperável) incluído na nota fiscal: R$ 18.000,00. Frete para transporte das mercadorias até a empresa, pago pela Sociedade Empresária “A”: R$ 4.000,00. Considerando as regras da NBC TG 16 (R2) – ESTOQUES, o valor inicial a ser registrado na conta de Estoques é de',null,'{"original": ["/cfc-2026-2/q18-1.png"]}','["R$ 86.000,00.", "R$ 100.000,00.", "R$ 82.000,00.", "R$ 104.000,00."]'::jsonb,'A',null from public.exams where slug='cfc-2026-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,19,'Ciências Contábeis','O Departamento jurídico da Empresa Ltda. apresentou parecer acerca dos seguintes casos que envolvem situações jurídicas e fiscais em andamento: • CASO 1: Autuação Fiscal: Auto de infração recebido do fisco Federal. A probabilidade de perda é avaliada como PROVÁVEL, sendo possível fazer uma estimativa confiável do valor. • CASO 2: Ação Cível: Processo movido por um cliente por danos morais. A probabilidade de perda é classificada como POSSÍVEL. • CASO 3: Processo Trabalhista: Ação judicial movida por um empregado. Os advogados da empresa classificam a perda como REMOTA. De acordo com as informações do departamento jurídico da empresa e as determinações da NBC TG 25 (R2) – PROVISÕES, PASSIVOS CONTINGENTES E ATIVOS CONTINGENTES, assinale a opção correta a respeito da forma como a empresa deve proceder em relação ao reconhecimento contábil e à evidenciação em notas explicativas para os três casos apresentados.',null,'{"original": ["/cfc-2026-2/q19-1.png"]}','["CASO 1: Reconhecer a provisão no Passivo e divulgar em notas explicativas; CASO 2: Não reconhecer no Passivo, apenas divulgar como passivo contingente em nota explicativa; CASO 3: Não reconhecer e nem divulgar em notas explicativas.", "CASO 1: Não reconhecer no Passivo, apenas divulgar como passivo contingente em nota explicativa; CASO 2: Reconhecer provisão no Passivo; CASO 3: Não reconhecer no Passivo, apenas divulgar como passivo contingente em nota explicativa.", "CASO 1: Não reconhecer e nem divulgar em notas explicativas; CASO 2: Não reconhecer no Passivo, apenas divulgar como passivo contingente em nota explicativa; CASO 3: Reconhecer provisão no Passivo.", "CASO 1: Reconhecer a provisão no Passivo; CASO 2: Não reconhecer e nem divulgar em notas explicativas; CASO 3: Não reconhecer e nem divulgar em notas explicativas."]'::jsonb,'A',null from public.exams where slug='cfc-2026-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,20,'Ciências Contábeis','Relacione os conceitos de bases de mensuração do valor atual previstos na NBC TG ESTRUTURA CONCEITUAL para relatório financeiro, apresentados na primeira coluna, com seus respectivos significados, descritos na segunda coluna. ( ) É o preço que seria recebido pela venda de ativo ou que seria pago pela transferência de passivo em transação ordenada entre participantes do mercado na data de mensuração. ( ) É o valor presente do caixa, ou de outros recursos econômicos, que a entidade espera ser 1. Valor Justo obrigada a transferir para cumprir a obrigação. 2. Valor em uso ( ) É o valor presente dos fluxos de caixa, ou outros benefícios econômicos, que a entidade 3. Custo corrente espera obter do uso de ativo e de sua alienação final. 4. Valor de cumprimento ( ) É a contraprestação que seria paga pelo ativo equivalente na data de mensuração mais os custos de transação que seriam incorridos nessa data, ou a contraprestação que seria recebida pelo passivo equivalente na data de mensuração menos os custos de transação que seriam incorridos nessa data. A relação correta, na ordem apresentada, é:',null,'{"original": ["/cfc-2026-2/q20-1.png"]}','["4 – 2 – 3 – 1.", "1 – 4 – 2 – 3.", "2 – 3 – 1 – 4.", "3 – 4 – 2 – 1."]'::jsonb,'B',null from public.exams where slug='cfc-2026-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,21,'Ciências Contábeis','Uma empresa comercial apresentou os seguintes dados e valores referentes à folha de pagamento de seus empregados do mês de agosto de 2026: • Salários Brutos: R$ 100.000,00, a serem pagos em setembro; • Contribuição Previdenciária retida dos empregados (INSS): R$ 11.000,00; • Imposto de Renda Retido na Fonte (IRRF): R$ 4.000,00. Considerando exclusivamente essas informações, assinale a opção que apresenta corretamente o reconhecimento da apropriação dos salários e retenções no mês de agosto de 2026.',null,'{"original": ["/cfc-2026-2/q21-1.png"]}','["Débito – Despesa com Salários (R$ 85.000,00); Débito – Passivo Circulante – INSS a Recolher (R$ 11.000,00); Débito – Passivo Circulante – IRRF a Recolher (R$ 4.000,00), e Crédito – Passivo Circulante – Salários a Pagar (R$ 100.000,00).", "Débito – Despesa com Salários (R$ 85.000,00); Débito – Despesa com INSS (R$ 11.0000,00); Débito – Despesa com IRRF (R$ 4.000,00), e Crédito – Passivo não Circulante – Salários a Pagar (R$ 100.000,00).", "Débito – Passivo Circulante – Salários a Pagar (R$ 100.000,00); Crédito – Despesa com Salários (R$ 85.000,00); Crédito – Passivo Circulante – INSS a Recolher (R$ 11.000,00), e Crédito – Passivo Circulante – IRRF a Recolher (R$ 4.000,00).", "Débito – Despesa com Salários (R$ 100.000,00); Crédito – Passivo Circulante – Salários a Pagar (R$ 85.000,00); Crédito – Passivo Circulante – INSS a Recolher (R$ 11.000,00), e Crédito – Passivo Circulante – IRRF a Recolher (R$ 4.000,00)."]'::jsonb,'D',null from public.exams where slug='cfc-2026-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,22,'Ciências Contábeis','Em junho de 2026, uma entidade contratou um professor externo para ministrar um curso sobre inteligência artificial a seus empregados, por R$ 12.000,00. O valor foi pago em três parcelas iguais, em junho, julho e agosto de 2026. Metade das aulas foi ministrada em junho, e o restante, em julho. De acordo com o Regime de Competência, a despesa com o professor na Demonstração do Resultado mensal da entidade, em 30/06/2026, foi',null,'{"original": ["/cfc-2026-2/q22-1.png"]}','["zero.", "R$ 4.000,00.", "R$ 6.000,00.", "R$ 12.000,00."]'::jsonb,'C',null from public.exams where slug='cfc-2026-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,23,'Ciências Contábeis','Em 31/12/2025, a Cia Gama reconheceu a distribuição de R$ 50.000,00 a título de dividendos mínimos obrigatórios. O valor foi pago aos acionistas da empresa em 2026. Ao analisar a Demonstração de Mutações do Patrimônio Líquido anual da Cia Gama, em 31/12/2025, pôde-se constatar que, em decorrência da distribuição dos dividendos obrigatórios, o total do patrimônio líquido',null,'{"original": ["/cfc-2026-2/q23-1.png"]}','["diminuiu.", "aumentou.", "permaneceu o mesmo, assim como o saldo das contas.", "permaneceu o mesmo, mas houve modificações nos saldos das contas."]'::jsonb,'A',null from public.exams where slug='cfc-2026-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,24,'Ciências Contábeis','Em 01/01/2025, a Cia XYZ comprou um veículo para utilizar em seus negócios por R$ 50.000,00, à vista. Na data, a entidade planejava utilizar o veículo durante cinco anos. No entanto, em 31/12/2025, os gestores da Cia XYZ constataram que o veículo era pouco utilizado e o venderam por R$ 42.000,00, à vista. A Cia XYZ utiliza o método da linha reta para depreciar os seus ativos imobilizados e considera valor residual nulo. Considerando apenas esses fatos, em 31/12/2025, na Demonstração dos Fluxos de Caixa anual da entidade, a atividade de investimento',null,'{"original": ["/cfc-2026-2/q24-1.png"]}','["gerou líquido R$ 2.000,00.", "gerou líquido R$ 42.000,00.", "consumiu líquido R$ 8.000,00.", "consumiu líquido R$ 10.000,00."]'::jsonb,'C',null from public.exams where slug='cfc-2026-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,25,'Ciências Contábeis','Em 31/12/2025, a Cia. KMLK não apresentou, em sua Demonstração do Valor Adicionado, saldo no item “Valor Adicionado Recebido em Transferência”. O fato de a empresa não apresentar valor nesse item pode indicar que a Cia. KMLK',null,'{"original": ["/cfc-2026-2/q25-1.png"]}','["presta as suas atividades em imóvel próprio.", "não possui investimento em controladas e coligadas.", "não reconheceu perda de recuperabilidade de seus ativos.", "tem todo o serviço realizado por mão de obra contratada."]'::jsonb,'B',null from public.exams where slug='cfc-2026-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,26,'Ciências Contábeis','Em 31/12/2025, a Cia. Alfa apresentava os seguintes saldos em seu Balanço Patrimonial: • Disponibilidades: R$ 300.000,00; • Capital Social: R$ 300.000,00. Já a Cia. Beta apresentava os seguintes saldos: • Disponibilidades: R$ 12.000,00; • Terrenos: R$ 40.000,00; • Capital Social: R$ 52.000,00. Em 01/01/2026, a Cia. Alfa adquiriu 100% de participação na Cia. Beta por R$ 90.000,00, que corresponde ao valor justo dessa participação. Na data, foi avaliado que os terrenos tinham valor de mercado de R$ 45.000,00. Além disso, no processo de apropriação do preço pago, foi atribuído à marca da Cia. Beta um valor de R$ 18.000,00. Ainda, foi avaliado que a Cia. Beta possuía empregados bem treinados e com grande capacidade de geração de benefícios futuros. Assinale a opção que indica o goodwill reconhecido pela Cia. Alfa na data da compra, em seu Balanço Patrimonial, de acordo com a NBC TG 15 (R4) – COMBINAÇÃO DE NEGÓCIOS.',null,'{"original": ["/cfc-2026-2/q26-1.png"]}','["R$ 15.000,00.", "R$ 27.000,00.", "R$ 33.000,00.", "R$ 38.000,00."]'::jsonb,'A',null from public.exams where slug='cfc-2026-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,27,'Ciências Contábeis','A companhia Delta possuía, em 31/12/2025: numerário em caixa no valor de R$ 40.000,00; valores a receber de no valor de R$ 10.000,00 referentes a vendas entregues; e patrimônio líquido no valor de R$ 50.000,00. Em janeiro de 2026, a diretoria da empresa aprovou a intenção de comprar novos equipamentos avaliados em R$ 30.000,00 no mês seguinte. Concomitantemente, a entidade firmou um contrato para serviços de manutenção, ainda não prestados, a terceiro, no valor de R$ 15.000,00. Nenhum valor foi recebido. Por fim, a contabilidade reconheceu uma dívida de R$ 25.000,00 referente à compra de matérias-primas que já foram recebidas no estoque. O contador da companhia apura os totais monetários que cumprem, rigorosamente, as definições contábeis exigidas pela norma. Em relação à classificação e à totalização dos elementos patrimoniais descritos, avalie se cada afirmativa a seguir é verdadeira (V) ou falsa (F). I. O total de ativos da entidade soma R$ 80.000,00, uma vez que a intenção de aquisição futura dos equipamentos atende à definição normativa de recurso econômico presente controlado por evento passado. II. O passivo da entidade totaliza estritamente R$ 25.000,00, caracterizando-se como a única obrigação presente de transferir um recurso econômico resultante da ocorrência de um evento já passado. III. O contrato de manutenção firmado eleva as obrigações para R$ 40.000,00, pois a assinatura documental por si só caracteriza o recebimento de benefícios econômicos e o surgimento de um passivo imediato. À luz das definições de ativos e passivos preconizadas pela NBC TG ESTRUTURA CONCEITUAL, está correto o que se afirma em',null,'{"original": ["/cfc-2026-2/q27-1.png"]}','["I e III, apenas.", "III, apenas.", "II, apenas.", "I e II, apenas."]'::jsonb,'C',null from public.exams where slug='cfc-2026-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,28,'Ciências Contábeis','Ao longo de 2021, a Controladora Alfa vendeu mercadorias para sua controlada Beta por R$ 500.000,00. O custo das mercadorias era de R$ 350.000,00. Em 31/12/2021, 40% dessas mercadorias permaneciam em estoque na controlada. Na elaboração das demonstrações consolidadas de acordo com a NBC TG 36 (R3) – DEMONSTRAÇÕES CONSOLIDADAS, o lucro não realizado que deverá ser eliminado é de',null,'{"original": ["/cfc-2026-2/q28-1.png"]}','["R$ 60.000,00.", "R$ 90.000,00.", "R$ 120.000,00.", "R$ 150.000,00."]'::jsonb,'A',null from public.exams where slug='cfc-2026-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,29,'Ciências Contábeis','A empresa “F” S.A. iniciou suas atividades em 01/11/2025 com as seguintes operações no primeiro mês: • Subscrição e integralização total de Capital no valor de R$ 200.000,00 em depósito bancário. • Compra de mercadorias para revenda no valor de R$ 50.000,00, a prazo, para pagamento em 60 dias. • Prestação de serviços a clientes no valor de R$ 30.000,00, recebida integralmente à vista, por PIX. • Pagamento à vista de despesas gerais do mês no valor de R$ 5.000,00. Considerando apenas as operações descritas e aplicando o regime de competência para a apuração do resultado do exercício, os valores do Ativo Total e do Patrimônio Líquido no Balanço Patrimonial de 30/11/2025 foram, respectivamente,',null,'{"original": ["/cfc-2026-2/q29-1.png"]}','["R$ 225.000,00 e R$ 225.000,00.", "R$ 275.000,00 e R$ 225.000,00.", "R$ 275.000,00 e R$ 200.000,00.", "R$ 225.000,00 e R$ 175.000,00."]'::jsonb,'B',null from public.exams where slug='cfc-2026-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,30,'Ciências Contábeis','Em 10/06/2025, a empresa “CD” S.A. realizou, em 10/06/20X5, o pagamento em atraso de uma duplicata de sua responsabilidade no valor nominal de R$ 10.000,00. Em decorrência do atraso, a instituição bancária processou uma transferência eletrônica total no valor de R$ 10.500,00, sendo liquidadas as condições contratuais com a inclusão de R$ 500,00 relativos a juros de mora, uma despesa financeira. O contador, ao registrar a operação no livro diário, deve realizar o seguinte lançamento contábil:',null,'{"original": ["/cfc-2026-2/q30-1.png"]}','["Débito: Duplicatas a pagar R$ 10.000,00 Débito: Despesas com juros R$ 500,00 Crédito: Bancos R$ 10.500,00", "Débito: Duplicatas a pagar R$ 10.500,00 Crédito: Bancos R$ 10.500,00", "Débito: Duplicatas a pagar R$ 11.000,00 Crédito: Despesas com juros R$ 500,00 Crédito: Bancos R$ 10.500,00", "Débito: Bancos R$ 10.500,00 Crédito: Duplicatas a pagar R$ 10.000,00 Crédito: Despesas com juros R$ 500,00"]'::jsonb,'A',null from public.exams where slug='cfc-2026-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,31,'Ciências Contábeis','O departamento de contabilidade da empresa "Qui” S.A. extraiu os seguintes saldos das suas contas patrimoniais em 31/12/20X5, antes da estruturação final do Balanço Patrimonial: • Caixa e equivalentes de caixa: R$ 15.000,00; • Duplicatas a receber (vencimento em até 60 dias): R$ 45.000,00; • Perdas estimadas com créditos de liquidação duvidosa: R$ 2.000,00; • Estoques de mercadorias para revenda: R$ 25.000,00; • Adiantamento a fornecedor de curto prazo: R$ 10.000,00; • Adiantamento de Clientes: R$ 14.000,00; • Veículos para uso nas entregas: R$ 50.000,00; • Fornecedores (vencimento em 90 dias): R$ 30.000,00. Com base estritamente nas normas de apresentação e classificação do Balanço Patrimonial, assinale a opção que apresenta o valor total líquido a ser evidenciado no subgrupo do Ativo Circulante.',null,'{"original": ["/cfc-2026-2/q31-1.png"]}','["R$ 83.000,00.", "R$ 93.000,00.", "R$ 95.000,00.", "R$ 97.000,00."]'::jsonb,'B',null from public.exams where slug='cfc-2026-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,32,'Ciências Contábeis','A empresa “Q” construiu uma máquina em 2024 para utilizar na fabricação do seu principal produto. Os custos para a construção foram de R$ 410.000,00. Esse ativo passou a estar em condições de funcionamento em 01/02/2025. Nesse momento, foi estimado que o ativo seria vendido ao final de sua vida útil por R$ 50.000,00. A vida útil estimada foi de 30 anos. Devido a uma mudança nas condições de mercado, em 01/11/2025 foi realizada uma nova estimativa de vida útil, que passou a ser de 25 anos, a partir da data da nova mensuração, enquanto o valor de venda estimado ao final da utilização do ativo passou para R$ 30.000,00. A empresa “Q” utiliza o método linear para o cálculo da depreciação e apura e divulga demonstrações contábeis mensalmente. Com base nessas informações, assinale a opção que apresenta a despesa de depreciação que deve ser registrada em 2025.',null,'{"original": ["/cfc-2026-2/q32-1.png"]}','["R$ 13.527,51.", "R$ 13.933,33.", "R$ 11.473,33.", "R$ 11.000,00."]'::jsonb,'C',null from public.exams where slug='cfc-2026-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,33,'Ciências Contábeis','Uma empresa possuía no início do mês saldo na conta de estoques no valor de R$ 8.000,00, representando 100 unidades. Ao longo do mês realizou as seguintes operações: • Dia 2: aquisição de 100 unidades por R$ 100,00 cada; • Dia 10: venda de 100 unidades por R$ 200,00 cada; • Dia 15: aquisição de 200 unidades por R$ 120,00 cada; • Dia 20: venda de 200 unidades por R$ 230,00 cada; • Dia 25: aquisição de 100 unidades por R$ 130,00 cada. Desconsiderando qualquer tributação sobre as operações e sabendo que a empresa adota o custo médio ponderado móvel como método de mensuração de seus estoques, o valor do saldo final de estoques dessa empresa é de',null,'{"original": ["/cfc-2026-2/q33-1.png"]}','["R$ 21.000,00.", "R$ 22.000,00.", "R$ 24.000,00.", "R$ 25.000,00."]'::jsonb,'C',null from public.exams where slug='cfc-2026-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,34,'Ciências Contábeis','A Fábrica de Utensílios Domésticos JP Ltda. realiza sua produção em um único departamento, fabricando dois tipos de colheres: colheres de sobremesa e colheres de sopa. Em determinado período, foram apurados os seguintes dados: Colheres de sobremesa: • Mão de obra direta (MOD): R$ 26.250,00; • Material direto: R$ 12.000,00; • Tempo de produção (horas/máquina): 22.400. Colheres de sopa: • Mão de obra direta (MOD): R$ 8.750,00; • Material direto: R$ 18.000,00; • Tempo de produção (horas/máquina): 9.600. O valor total dos Custos Indiretos de Produção (CIP) no período foi de R$ 140.000,00. Com base nessas informações, assinale a afirmativa correta.',null,'{"original": ["/cfc-2026-2/q34-1.png"]}','["R$ 35.000,00 de CIP foram alocados às colheres de sopa, utilizando-se o critério da proporcionalidade ao custo de Mão de Obra Direta (MOD).", "R$ 84.000,00 de CIP foram alocados às colheres de sobremesa, utilizando-se o critério da proporcionalidade ao custo de Material Direto.", "R$ 98.000,00 de CIP foram alocados às colheres de sopa, utilizando-se o critério da proporcionalidade ao tempo de Horas/Máquina.", "R$ 56.000,00 de CIP foram alocados às colheres de sobremesa, utilizando-se o critério da proporcionalidade ao custo de mão de obra direta (MOD)."]'::jsonb,'A',null from public.exams where slug='cfc-2026-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,35,'Ciências Contábeis','A empresa Roupas em Linho LTDA. produz camisas e camisetas. Os dados relacionados aos dois produtos são apresentados a seguir: Descrição Camisas Camisetas Quantidade Produzida 500 450 A empresa fez o seguinte levantamento dos Custos das Atividades e Direcionadores Direcionadores Departamento Atividades Direcionadores Custos Camisas Camisetas Total Compras Comprar Materiais nº de pedidos 20.000,00 200 100 300 Desenvolver Fornecedores nº de fornecedores 12.000,00 4 6 10 Corte e Costura Cortar tempo de corte 25.000,00 6 6 12 Colar tempo para colar 25.600,00 16 8 24 Acabamento Acabar tempo de acabamento 18.000,00 4 10 14 Despachar Produtos tempo de despacho 30.200,00 5 5 10 Os custos unitários de matéria-prima são: • Camisa = R$ 20,00; • Camiseta = R$ 10,00. A partir da análise e observação das informações da empresa Roupas em Linho LTDA. assinale a opção que corresponde ao custo unitário para produzir Camisas e Camisetas, respectivamente, pelo método do Custeio ABC.',null,'{"original": ["/cfc-2026-2/q35-1.png"]}','["Camisas R$ 125,69; Camisetas R$ 116,13.", "Camisas R$ 155,89; Camisetas R$ 149,68.", "Camisas R$ 129,22; Camisetas R$ 134,87.", "Camisas R$ 139,89; Camisetas R$ 139,65."]'::jsonb,'B',null from public.exams where slug='cfc-2026-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,36,'Ciências Contábeis','Uma indústria realizou os seguintes eventos durante determinado período: Evento Valor (R$) Compra de matéria-prima 18.000,00 Consumo de matéria-prima na produção 12.000,00 Aquisição de máquinas para a fábrica 40.000,00 Depreciação das máquinas utilizadas na produção 2.500,00 Salários das equipes jurídica e de marketing 6.000,00 Comissão sobre vendas (remuneração dos vendedores) 3.000,00 Com base nos conceitos de custos, despesas e investimentos, o valor total dos custos incorridos no período foi de',null,'{"original": ["/cfc-2026-2/q36-1.png"]}','["R$ 14.500,00.", "R$ 18.000,00.", "R$ 17.500,00.", "R$ 72.500,00."]'::jsonb,'A',null from public.exams where slug='cfc-2026-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,37,'Ciências Contábeis','Uma loja vendia mochilas. Em 01/08/2026 não havia mochilas em estoque. Na data, a loja adquiriu 200 mochilas pelo total de R$ 16.000,00. O frete pago para o recebimento das mochilas foi de R$ 400,00. Em agosto de 2026, 180 mochilas foram vendidas, sendo que a receita da loja foi de R$ 36.000,00. A loja paga comissão a seus vendedores de 5% sobre o preço da mochila vendida. A margem de contribuição unitária da mochila foi de',null,'{"original": ["/cfc-2026-2/q37-1.png"]}','["R$ 108,00.", "R$ 110,00.", "R$ 118,00.", "R$ 120,00."]'::jsonb,'A',null from public.exams where slug='cfc-2026-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,38,'Ciências Contábeis','Uma empresa está estudando quais quantidades deve produzir para chegar aos seus pontos de equilíbrio contábil, econômico e financeiro. Para isso, seu contador levantou as seguintes informações referentes ao mês de junho de 2026: • Custos fixos: R$ 400.000,00; • Despesas fixas: R$ 100.000,00; • Custos variáveis: R$ 200,00/unidade; • Despesas variáveis: R$ 50,00/unidade; • Preço unitário de venda: R$ 750,00; • Custo de oportunidade: R$ 500.000,00; • Parcela não desembolsável dos custos: R$ 250.000,00. Com base nos dados levantados pelo contador, os pontos de equilíbrio contábil, econômico e financeiro dessa empresa são, respectivamente,',null,'{"original": ["/cfc-2026-2/q38-1.png"]}','["1.000 unidades, 1.800 unidades e 1.500 unidades.", "1.000 unidades, 2.000 unidades e 500 unidades.", "1.500 unidades, 1.800 unidades e 800 unidades.", "1.500 unidades, 1.700 unidades e 300 unidades."]'::jsonb,'B',null from public.exams where slug='cfc-2026-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,39,'Ciências Contábeis','Um administrador deseja verificar qual é a relação entre a receita de vendas e o custo das mercadorias vendidas. Para a obtenção da informação, é recomendável que seja realizada a análise',null,'{"original": ["/cfc-2026-2/q39-1.png"]}','["vertical do Balanço Patrimonial.", "horizontal do Balanço Patrimonial.", "vertical da Demonstração do Resultado.", "horizontal da Demonstração do Resultado."]'::jsonb,'C',null from public.exams where slug='cfc-2026-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,40,'Ciências Contábeis','Uma empresa, buscando captar um empréstimo junto a uma instituição financeira, apurou seus indicadores de liquidez para verificar sua capacidade de pagamento. O contador apurou o seguinte balanço patrimonial dos 2 últimos anos: ATIVO 31/12/24 31/12/25 Disponível R$ 300.000,00 R$ 400.000,00 Contas a Receber no Curto Prazo R$ 500.000,00 R$ 600.000,00 Estoques R$ 500.000,00 R$ 800.000,00 Realizável a Longo Prazo R$ 700.000,00 R$ 1.200.000,00 TOTAL R$ 2.000.000,00 R$ 3.000.000,00 PASSIVO + PL 31/12/24 31/12/25 Fornecedores R$ 400.000,00 R$ 1.100.000,00 Empréstimos de Curto Prazo R$ 100.000,00 R$ 500.000,00 Empréstimos de Longo Prazo R$ 500.000,00 R$ 400.000,00 Patrimônio Líquido R$ 1.000.000,00 R$ 1.000.000,00 TOTAL R$ 2.000.000,00 R$ 3.000.000,00 Com base nesses dados, os indicadores de liquidez geral da empresa nos anos de 2024 e 2025 foram, respectivamente,',null,'{"original": ["/cfc-2026-2/q40-1.png"]}','["1,0 e 1,0.", "1,6 e 0,6.", "2,6 e 1,1.", "2,0 e 1,5."]'::jsonb,'D',null from public.exams where slug='cfc-2026-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,41,'Ciências Contábeis','O Município ABC está desenvolvendo um projeto para reconhecimento dos bens do patrimônio cultural no Balanço Patrimonial. Nas reuniões para mensuração e evidenciação dos referidos ativos, foram mapeadas dificuldades em potencial na representação contábil do fenômeno de forma completa, neutra e livre de erro material. Com base na NBC TSP – ESTRUTURA CONCEITUAL, o reconhecimento dos bens do patrimônio cultural, nessas condições, descumpre a seguinte característica qualitativa da informação contábil:',null,'{"original": ["/cfc-2026-2/q41-1.png"]}','["relevância.", "representação fidedigna.", "compreensibilidade.", "verificabilidade."]'::jsonb,'B',null from public.exams where slug='cfc-2026-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,42,'Ciências Contábeis','Os Princípios Orçamentários visam estabelecer diretrizes norteadoras básicas, a fim de conferir racionalidade, eficiência e transparência para os processos de elaboração, execução e controle do orçamento público. Com base nos princípios orçamentários aplicáveis ao setor público brasileiro, conforme apresentados no Manual de Contabilidade Aplicada ao Setor Público (MCASP), analise os casos a seguir: • Caso 1: Um município elaborou dois documentos orçamentários para o mesmo exercício: uma Lei Orçamentária Anual para a administração direta e outro documento orçamentário separado para as autarquias municipais. • Caso 2: A Lei Orçamentária Anual de um município foi elaborada para vigorar por dois anos consecutivos, prevendo receitas e despesas para o período de 2025 a 2026. • Caso 3: Na elaboração da Lei Orçamentária Anual de determinado estado, as receitas e despesas de uma fundação pública estadual não foram incluídas na Lei Orçamentária Anual, sendo registradas apenas em relatórios internos da própria entidade. Os casos 1, 2 e 3 estão infringindo os seguintes princípios orçamentários, respectivamente:',null,'{"original": ["/cfc-2026-2/q42-1.png"]}','["exclusividade; legalidade; e unidade ou totalidade.", "universalidade; unidade ou totalidade; e exclusividade.", "unidade ou totalidade; anualidade ou periodicidade; e universalidade.", "legalidade; orçamento bruto; e unidade ou totalidade."]'::jsonb,'C',null from public.exams where slug='cfc-2026-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,43,'Ciências Contábeis','Em junho de 2026, um posto de saúde aplicou 3.000 doses de vacina. Em julho, o posto foi acionado na Justiça por um grupo de pessoas que tiveram fortes reações atribuídas às vacinas e pediam uma indenização. A Procuradoria Jurídica da Secretaria de Saúde à qual o posto de saúde encontra-se vinculado emitiu parecer que considerou que a probabilidade da saída de recursos, em decorrência da causa judicial era remota, de modo que não houve reconhecimento em contas patrimoniais. Nesse caso, a divulgação em notas explicativas é',null,'{"original": ["/cfc-2026-2/q43-1.png"]}','["proibida.", "dispensada.", "incentivada.", "obrigatória."]'::jsonb,'B',null from public.exams where slug='cfc-2026-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,44,'Ciências Contábeis','Ao encerrar o exercício financeiro, a equipe contábil de um município analisava os procedimentos de execução da despesa orçamentária. Em reunião, surgiram dúvidas acerca dos efeitos do empenho, das características da liquidação e dos requisitos para a realização do pagamento pela Administração Pública. Considerando esse contexto, analise as afirmativas a seguir. I. O empenho da despesa cria para o Estado a obrigação de pagamento, pendente ou não de implemento de condição. II. A liquidação da despesa consiste na verificação do direito adquirido pelo credor, com base nos títulos e documentos comprobatórios do respectivo crédito. III. O pagamento da despesa pode ocorrer independentemente da liquidação prévia, desde que haja previsão contratual ou mera conveniência administrativa para a antecipação do desembolso. IV. A etapa da execução da despesa orçamentária percorre, em regra, os estágios de empenho, liquidação e pagamento. Estão corretas as afirmativas',null,'{"original": ["/cfc-2026-2/q44-1.png"]}','["I e II, apenas.", "I, II e IV, apenas.", "II, III e IV, apenas.", "I, III e IV, apenas."]'::jsonb,'B',null from public.exams where slug='cfc-2026-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,45,'Ciências Contábeis','Uma entidade deseja elaborar o seu orçamento de 2026, começando pela projeção da receita bruta de vendas. As seguintes informações foram estimadas para 2026: I. Projeção do número de unidades vendidas. II. Projeção do preço a ser praticado. III. Projeção do aluguel das lojas. Para estimar o valor da receita bruta de vendas, a entidade deve levar em consideração o que se apresenta em:',null,'{"original": ["/cfc-2026-2/q45-1.png"]}','["I, somente.", "I e II, somente.", "I e III, somente.", "II e III, somente."]'::jsonb,'B',null from public.exams where slug='cfc-2026-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,46,'Ciências Contábeis','Uma determinada empresa, do ramo de varejo, contratou uma firma de auditoria, para verificar as demonstrações contábeis do ano anterior. O presidente da empresa de ramo de varejo esperava que a asseguração de uma auditoria trouxesse credibilidade para sua empresa no ramo, por trazer um maior grau de confiança às demonstrações contábeis. Considerando os dizeres da NBC TA 200 (R1) – OBJETIVOS GERAIS DO AUDITOR INDEPENDENTE E A CONDUÇÃO DA AUDITORIA EM CONFORMIDADE COM NORMAS DE AUDITORIA, é correto afirmar que o presidente da empresa do ramo de varejo estava',null,'{"original": ["/cfc-2026-2/q46-1.png"]}','["errado, pois a auditoria independente tem como objetivo assegurar a continuidade e a viabilidade do negócio analisado.", "certo, porque a auditoria visa, principalmente, à verificação de fraudes e erros.", "certo, pois o objetivo da auditoria é obter segurança razoável de que as demonstrações contábeis como um todo estão livres de distorção relevante.", "errado, pois cabe à auditoria externa auxiliar a Administração na elaboração das demonstrações contábeis."]'::jsonb,'C',null from public.exams where slug='cfc-2026-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,47,'Ciências Contábeis','De acordo com a NBC TA 705 – MODIFICAÇÕES NA OPINIÃO DO AUDITOR INDEPENDENTE, quando o auditor prevê modificar a opinião no seu relatório, ele deve comunicar aos responsáveis pela governança as circunstâncias que levaram à modificação prevista e o texto proposto da modificação. Isso permite que os responsáveis pela governança, quando apropriado, tenham a oportunidade de',null,'{"original": ["/cfc-2026-2/q47-1.png"]}','["aumentar os honorários previstos inicialmente.", "comunicar, previamente, o fato às entidades reguladoras.", "fornecer ao auditor informações e explicações adicionais sobre os assuntos que deram origem às modificações previstas.", "contratar outra firma de auditoria para fornecer um relatório com informações e explicações que deram origem às modificações previstas."]'::jsonb,'C',null from public.exams where slug='cfc-2026-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,48,'Ciências Contábeis','Durante a auditoria das demonstrações contábeis da Companhia Beta S.A., referentes ao exercício findo em 31 de dezembro de 2025, o auditor identificou que a entidade apresentou prejuízo de R$ 30 milhões no exercício e que o passivo circulante excedia o ativo circulante em R$ 35 milhões nas demonstrações contábeis individuais e em R$ 32 milhões nas demonstrações contábeis consolidadas. Essas condições estão adequadamente divulgadas na nota explicativa nº 3, na qual a administração também descreve as ações que está implementando para restabelecer o equilíbrio econômico-financeiro da companhia. O auditor concluiu que tais eventos indicam a existência de incerteza relevante que pode levantar dúvida significativa quanto à capacidade de continuidade operacional, mas verificou que a divulgação nas demonstrações contábeis é apropriada, adequada e suficiente. Nessas circunstâncias, o relatório do auditor independente deve conter',null,'{"original": ["/cfc-2026-2/q48-1.png"]}','["opinião com ressalva, em razão da deterioração da posição financeira da companhia.", "opinião adversa, em razão do prejuízo relevante apresentado no exercício.", "abstenção de opinião, em razão da incerteza quanto à continuidade operacional.", "parágrafo de ênfase, chamando a atenção para a nota explicativa que descreve a incerteza relacionada à continuidade operacional."]'::jsonb,'D',null from public.exams where slug='cfc-2026-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,49,'Ciências Contábeis','No âmbito de uma perícia judicial, o perito contábil nomeado, Dr. Y, concluiu os trabalhos e protocolou o laudo. O assistente técnico indicado pela parte autora, contador X, discordou dos critérios de avaliação patrimonial adotados e pretende elaborar seu parecer técnico contábil. Ocorre que a avaliação dos ativos imóveis foi realizada exclusivamente por engenheiro de avaliações, profissional de outra área, sem participação técnica de Dr. Y. O assistente X cogita subscrever o laudo do engenheiro como forma de validá-lo, para ampliar a força probatória da perícia. Considerando a NBC TP 01 (R2) – PERÍCIA CONTÁBIL, a conduta de X, ao subscrever o laudo do engenheiro, seria',null,'{"original": ["/cfc-2026-2/q49-1.png"]}','["lícita, desde que X declare expressamente que se responsabiliza apenas pela parte contábil do documento.", "lícita, pois o assistente técnico pode validar laudo de especialista de outra área quando o objeto da perícia for multidisciplinar.", "vedada, pois é defeso ao assistente técnico validar, ratificar ou subscrever laudo elaborado por profissional de outra área; X deve oferecer seu próprio parecer técnico contábil.", "vedada apenas se o laudo do engenheiro não tiver sido homologado pelo juízo, sendo lícita após a homologação."]'::jsonb,'C',null from public.exams where slug='cfc-2026-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,50,'Ciências Contábeis','A perita contábil Dra. W foi contratada para realizar perícia extrajudicial voluntária, visando apurar haveres em dissolução parcial de sociedade empresária. Ao elaborar o laudo pericial contábil, W estruturou o documento com os seguintes elementos: identificação das partes; síntese do caso; síntese do objeto e do objetivo da perícia; relato das diligências; transcrição dos quesitos e respostas; e assinatura com número de CRC. Após análise técnica, a parte contrária apontou que o laudo carecia de elemento obrigatório previsto na NBC TP 01 (R2) – PERÍCIA CONTÁBIL. Nesse caso, o seguinte elemento obrigatório da estrutura mínima do laudo pericial contábil foi omitido por Dra. W:',null,'{"original": ["/cfc-2026-2/q50-1.png"]}','["o cronograma das diligências realizadas durante a execução da perícia.", "a fundamentação, contemplando o método científico adotado e a análise técnica e/ou científica realizada.", "a ata das reuniões técnicas realizadas com os assistentes técnicos das partes.", "o contrato de prestação de serviços firmado entre a perita e o contratante."]'::jsonb,'B',null from public.exams where slug='cfc-2026-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.exams(slug,title,source,year) values ('cfc-2026-1','CFC 2026.1 — Exame de Suficiência — Contador — Tipo 1','cfc','2026') on conflict(slug) do update set title=excluded.title,source=excluded.source,year=excluded.year;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,1,'Língua Portuguesa','Observe o seguinte texto de Bertrand Russell: A matemática, vista corretamente, possui não apenas verdade, mas também suprema beleza – uma beleza fria e austera, como a da escultura. Assinale a opção que mostra uma afirmação correta sobre o texto.',null,'{"original": ["/cfc-2026-1/q1-1.png"]}','["A frase mostra simultaneamente aspectos positivos e negativos da matemática.", "O emprego da expressão “não apenas verdade” abre a possibilidade de dizer-se “mas suprema beleza”.", "A expressão “uma beleza fria e austera” nega a afirmação anterior de que a matemática possui suprema beleza.", "Ao afirmar que a beleza da matemática é como a da escultura, a frase desvaloriza a escultura."]'::jsonb,'B',null from public.exams where slug='cfc-2026-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,2,'Língua Portuguesa','Nem sempre os números indicam uma quantidade precisa. Assinale a frase em que há precisão.',null,'{"original": ["/cfc-2026-1/q2-1.png"]}','["Os especialistas em contagem de público dizem que havia mais de um milhão de pessoas na passeata.", "O mesmo motorista envolvido no acidente de ontem já havia passado por três outras ocorrências semelhantes.", "Perto de mil veículos passaram pelo pedágio, no mesmo dia, em função do feriado.", "O vídeo mostrava cerca de 50 automóveis que estavam parados por causa do desmoronamento."]'::jsonb,'B',null from public.exams where slug='cfc-2026-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,3,'Matemática Financeira e Estatística','Uma empresa decidiu renovar parte de sua frota adquirindo novos veículos. Para não descapitalizar o caixa da empresa, a diretoria decidiu financiar R$ 240.000,00 junto a um banco. O contrato de financiamento prevê que a dívida seja quitada por meio de 30 pagamentos mensais, postecipados e consecutivos, de acordo com a tabela SAC (Sistema de Amortização Constante). Fica firmado que a taxa efetiva de juros permanecerá fixa em 4% ao mês, ao longo de toda a vigência do contrato. Considerando estritamente as condições descritas acima, é correto afirmar que o valor do quinto pagamento será de',null,'{"original": ["/cfc-2026-1/q3-1.png"]}','["R$ 8.320,00.", "R$ 16.000,00.", "R$ 16.320,00.", "R$ 17.600,00."]'::jsonb,'C',null from public.exams where slug='cfc-2026-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,4,'Matemática Financeira e Estatística','Um contador trabalha em uma firma de auditoria e foi alocado na equipe de Data Analytics. Sua tarefa é analisar o comportamento das vendas de uma rede varejista, para definir parâmetros de risco e identificar dias com faturamentos atípicos. Após extrair os dados, o contador constata que o faturamento diário da rede segue perfeitamente uma distribuição normal, com média igual a R$ 40.000,00. O contador também verifica que a probabilidade de que, em um dia aleatório, o faturamento esteja entre R$ 38.000,00 e R$ 42.000,00 é de 52%. Com base nessas informações, o contador conclui corretamente que a probabilidade de a rede varejista registrar faturamento diário inferior a R$ 38.000,00 é de',null,'{"original": ["/cfc-2026-1/q4-1.png"]}','["24%.", "26%.", "48%.", "76%."]'::jsonb,'A',null from public.exams where slug='cfc-2026-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,5,'Ciências Contábeis','Após a observância das formalidades constitucionais e legais, o Estado Alfa celebrou contrato administrativo com a sociedade empresária Beta, visando à construção de um prédio público moderno que atenderá, com eficiência e celeridade, aos anseios da coletividade. Registre-se, contudo, que a Administração Pública anteviu a necessidade de proceder à modificação do contrato administrativo em fase de execução, para melhor adequação às finalidades de interesse público. Nesse cenário, considerando as disposições da Lei nº 14.133/2021, é correto afirmar que o Estado Alfa',null,'{"original": ["/cfc-2026-1/q5-1.png"]}','["não poderá modificar o contrato administrativo, o qual, estando em fase de execução, é considerado lei entre as partes contratantes.", "poderá modificar o contrato administrativo, desde que haja concordância expressa ou tácita da sociedade empresária Beta.", "poderá modificar unilateralmente o contrato administrativo, respeitados os direitos do contratado.", "não poderá modificar o contrato administrativo, salvo em caso de autorização judicial."]'::jsonb,'C',null from public.exams where slug='cfc-2026-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,6,'Ciências Contábeis','O Município Alfa e o Estado Beta, em observância às formalidades legais, pretendem utilizar o sistema de registro de preços, procedimento auxiliar das licitações e contratações públicas. Busca-se, assim, a formalização, no âmbito das respectivas competências, de atas de registro de preços. Trata-se de documento vinculativo e obrigacional, com característica de compromisso para futura contratação, no qual são registrados o objeto, os preços, os fornecedores, os órgãos participantes e as condições a serem praticadas, conforme as disposições contidas no edital da licitação, no aviso ou instrumento de contratação direta e nas propostas apresentadas. Ao tomar conhecimento das pretensões dos referidos entes da Federação, o órgão público Charlie, integrante da Administração Pública Federal, demonstrou interesse em aderir, futuramente, às referidas atas de registro de preços, a serem gerenciadas pelo Município Alfa e pelo Estado Beta. Nesse cenário, considerando as disposições da Lei no 14.133/2021, é correto afirmar que o órgão público Charlie, integrante da Administração Pública Federal,',null,'{"original": ["/cfc-2026-1/q6-1.png"]}','["não poderá aderir às atas de registro de preços a serem gerenciadas pelo Município Alfa e pelo Estado Beta, salvo se houver a concordância expressa dos referidos entes federativos.", "poderá aderir à ata de registro de preços a ser gerenciada pelo Estado Beta, mas não à ata de registro de preços que será gerenciada pelo Município Alfa.", "poderá aderir à ata de registro de preços a ser gerenciada pelo Município Alfa, mas não à ata de registro de preços que será gerenciada pelo Estado Beta.", "não poderá aderir às atas de registro de preços a serem gerenciadas pelo Município Alfa e pelo Estado Beta."]'::jsonb,'D',null from public.exams where slug='cfc-2026-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,7,'Ciências Contábeis','A sociedade empresária Alfa, concessionária de serviços públicos no Município Beta, deparou-se com a necessidade, em um sábado, de proceder à interrupção do serviço prestado à coletividade residente e domiciliada no bairro Gama, sem aviso prévio, em razão de situação de emergência constatada na localidade. Nesse cenário, considerando as disposições da Lei nº 8.987/1995, é correto afirmar que',null,'{"original": ["/cfc-2026-1/q7-1.png"]}','["não se está diante de hipótese de descontinuidade do serviço, pois a interrupção, em caso de emergência ou motivada por razões de ordem técnica, independe de aviso prévio.", "não se está diante de hipótese de descontinuidade do serviço, pois a interrupção ocorreu em situação de emergência, dispensando aviso prévio.", "se está diante de hipótese de descontinuidade do serviço, pois a interrupção, ainda que em situação de emergência, não pode se iniciar no final de semana.", "se está diante de hipótese de descontinuidade do serviço, pois a interrupção, ainda que em situação de emergência, pressupõe aviso prévio."]'::jsonb,'B',null from public.exams where slug='cfc-2026-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,8,'Ciências Contábeis','Durante o encerramento do exercício, o contador da empresa “Q” Ltda. foi pressionado pela administração para postergar o reconhecimento de uma despesa relevante, com o objetivo de melhorar artificialmente o resultado do período. Considerando as disposições da NBC PG 01 – CÓDIGO DE ÉTICA PROFISSIONAL DO CONTADOR, a conduta profissional adequada é',null,'{"original": ["/cfc-2026-1/q8-1.png"]}','["atender à solicitação da administração, desde que o ajuste não gere impacto tributário relevante.", "ajustar temporariamente o resultado, caso a administração formalize por escrito a responsabilidade pela decisão.", "negociar a postergação da despesa para o exercício seguinte, buscando conciliar interesses empresariais e profissionais.", "manter a escrituração conforme as normas contábeis vigentes, preservando a integridade e a objetividade profissional, mesmo diante de pressões internas."]'::jsonb,'D',null from public.exams where slug='cfc-2026-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,9,'Ciências Contábeis','Uma firma de auditoria fora contratada para emitir relatório de asseguração sobre informações financeiras de determinada entidade e, posteriormente, ainda no mesmo exercício social, aceitou assumir decisões administrativas relacionadas à elaboração dessas mesmas informações. Considerando o papel da Contabilidade na sociedade e as disposições da NBC PG 100 (R1) – CUMPRIMENTO DO CÓDIGO, DOS PRINCÍPIOS FUNDAMENTAIS E DA ESTRUTURA CONCEITUAL e da NBC PG 01 – CÓDIGO DE ÉTICA PROFISSIONAL DO CONTADOR, a atuação adequada da firma de auditoria deve refletir a ideia de que',null,'{"original": ["/cfc-2026-1/q9-1.png"]}','["a independência pode ser relativizada se houver confiança mútua entre auditor e administração.", "a assunção de responsabilidade gerencial é aceitável quando não houver impacto financeiro relevante.", "a firma pode assumir funções administrativas desde que posteriormente reveja tecnicamente seu próprio trabalho.", "a firma não deve assumir responsabilidade de gestão, pois isso gera ameaças à independência e compromete o interesse público que fundamenta a atuação do contador."]'::jsonb,'D',null from public.exams where slug='cfc-2026-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,10,'Ciências Contábeis','De acordo com a NBC TG ESTRUTURA CONCEITUAL (R2) – ESTRUTURA CONCEITUAL PARA RELATÓRIO FINANCEIRO, ativo é um recurso econômico presente, controlado pela entidade como resultado de eventos passados. Um recurso econômico representa',null,'{"original": ["/cfc-2026-1/q10-1.png"]}','["um bem ou um direito que pertence à entidade.", "uma obrigação de transferir benefícios econômicos.", "um direito que tem o potencial de produzir benefícios econômicos.", "uma obrigação que resulta em aumento no patrimônio líquido, exceto quando referente a contribuições de detentores de direitos sobre o patrimônio."]'::jsonb,'C',null from public.exams where slug='cfc-2026-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,11,'Ciências Contábeis','Em 2024, uma empresa de varejo estimava inadimplência de 2% sobre o saldo de Clientes. Em 2025, buscando aumentar as vendas, a empresa reduziu as suas exigências para concessão de crédito aos clientes. Assim, uma análise criteriosa indicava que a inadimplência seria muito próxima de 5% nesse ano. No entanto, uma vez que os administradores da empresa são avaliados de acordo com o resultado operacional, eles escolheram continuar utilizando a estimativa anterior, de 2%. Ao avaliar se a informação contábil pode ser considerada representação fidedigna, é correto concluir que',null,'{"original": ["/cfc-2026-1/q11-1.png"]}','["pode ser, uma vez que é comparável.", "pode ser, uma vez que é tempestiva.", "não pode ser, uma vez que não é neutra.", "não pode ser, uma vez que não é verificável."]'::jsonb,'C',null from public.exams where slug='cfc-2026-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,12,'Ciências Contábeis','Em janeiro de 2026, uma entidade fabril assinou um contrato para a compra de uma máquina por R$ 50.000,00. O montante foi pago integralmente em fevereiro. A máquina foi recebida em março, quando foi instalada e disponibilizada para uso. No entanto, por decisão da entidade, a máquina começou a ser efetivamente utilizada em abril. No Balanço Patrimonial da entidade, a máquina deve ser reconhecida a partir de',null,'{"original": ["/cfc-2026-1/q12-1.png"]}','["janeiro.", "fevereiro.", "março.", "abril."]'::jsonb,'C',null from public.exams where slug='cfc-2026-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,13,'Ciências Contábeis','Em 01/03/2026, uma sociedade empresária adquiriu um equipamento de grande porte por um montante considerado relevante para ela. Para a aquisição, foram pagos R$ 100.000,00 à vista, e o restante tinha prazo para pagamento de 60 dias. Essa parcela complementar estava fixada em R$ 105.000,00, enquanto o seu valor presente na data da compra era de R$ 100.000,00. Assinale a opção que indica o custo histórico do passivo líquido no momento da compra, de acordo com a NBC TG ESTRUTURA CONCEITUAL (R2) – ESTRUTURA CONCEITUAL PARA RELATÓRIO FINANCEIRO:',null,'{"original": ["/cfc-2026-1/q13-1.png"]}','["R$ 100.000,00.", "R$ 105.000,00.", "R$ 200.000,00.", "R$ 205.000,00."]'::jsonb,'A/B/C/D/E',null from public.exams where slug='cfc-2026-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,14,'Ciências Contábeis','Uma empresa S.A. atua no setor de bebidas e possui diversas unidades de negócios. Entre elas, destacam-se as operações de “Cervejas” e “Refrigerantes”. A administração da companhia utiliza regularmente informações de desempenho dessas unidades para fins de avaliação de resultados e alocação de recursos, sendo tais informações analisadas pelo principal responsável pela tomada de decisões operacionais da entidade (CODM – Chief Operating Decision Maker). A empresa avaliou os seguintes indicadores referentes ao exercício: • A unidade Cervejas representa 12% da receita combinada de todos os segmentos operacionais. • A unidade Refrigerantes possui 9% da receita combinada, mas 11% dos ativos combinados dos segmentos operacionais. • Ambas as unidades têm suas informações regularmente revisadas pelo principal responsável pela tomada de decisões operacionais. Considerando as informações apresentadas e os preceitos da NBC TG 22 (R2) – INFORMAÇÕES POR SEGMENTO, é correto afirmar que',null,'{"original": ["/cfc-2026-1/q14-1.png"]}','["apenas o segmento Cervejas deve ser divulgado separadamente, pois somente ele ultrapassa o limite de 10% da receita combinada dos segmentos operacionais.", "apenas o segmento Refrigerantes, deve ser divulgado separadamente, pois o critério de ativos é suficiente para caracterizar segmento reportável.", "ambos os segmentos devem ser divulgados separadamente, pois cada um atende a, pelo menos, um dos critérios quantitativos previstos para segmentação reportável.", "nenhum dos segmentos deve ser divulgado separadamente, pois é necessário que o segmento atenda simultaneamente aos critérios de receita, resultado e ativos."]'::jsonb,'C',null from public.exams where slug='cfc-2026-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,15,'Ciências Contábeis','Uma empresa S.A. apresentou, em 31/12/2025, ativos fiscais diferidos decorrentes de prejuízos fiscais, bases negativas de contribuição social e diferenças temporárias dedutíveis, totalizando R$ 6.669.000,00 nas demonstrações individuais e R$ 7.121.000,00 nas demonstrações consolidadas. Conforme divulgado em nota explicativa, a realização desses ativos depende da geração futura de lucros tributáveis suficientes para permitir a compensação dos prejuízos fiscais e das bases negativas, bem como da reversão das diferenças temporárias dedutíveis. A administração elaborou projeções de resultados tributáveis futuros que suportam o reconhecimento desses ativos fiscais diferidos. O auditor independente incluiu, em seu relatório, parágrafo chamando a atenção para a nota explicativa, destacando a existência de incerteza relacionada ao prazo de realização dos ativos fiscais diferidos, mas afirmando que sua opinião não está ressalvada em relação a esse assunto. Considerando as informações apresentadas e os preceitos da NBC TG 32 (R4) – TRIBUTOS SOBRE O LUCRO, conclui-se que',null,'{"original": ["/cfc-2026-1/q15-1.png"]}','["a existência de prejuízos fiscais acumulados impede o reconhecimento de ativos fiscais diferidos, devendo tais valores ser reconhecidos somente quando ocorrer efetivamente lucro tributável suficiente para sua compensação.", "a entidade deve reconhecer ativo fiscal diferido decorrente de prejuízos fiscais, somente quando for provável a existência de lucro tributável futuro suficiente para sua compensação.", "os ativos fiscais diferidos decorrentes de prejuízos fiscais podem ser reconhecidos com base em estimativas de lucros tributáveis futuros elaboradas pela administração, independente da avaliação de probabilidade de realização.", "a inclusão de parágrafo, chamando a atenção no relatório do auditor, indica discordância quanto ao reconhecimento do ativo fiscal diferido e implica modificação na opinião de auditoria."]'::jsonb,'B',null from public.exams where slug='cfc-2026-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,16,'Ciências Contábeis','Uma companhia aberta brasileira atua no comércio varejista de bens de consumo por meio de lojas físicas e de plataforma digital. Em suas vendas on-line, a entidade também realiza o transporte das mercadorias por meio de logística própria. Em determinado dia, um cliente adquiriu um livro por meio do website da companhia. O pagamento foi realizado instantaneamente via PIX, e a nota fiscal eletrônica foi imediatamente emitida e enviada ao cliente por e-mail. O livro foi separado no centro de distribuição da empresa e despachado em caminhão pertencente à própria companhia, responsável pela entrega ao consumidor final. Durante o trajeto, antes da entrega ao cliente, o caminhão sofreu um acidente e parte das mercadorias transportadas foi completamente destruída, incluindo o livro adquirido pelo cliente. Considerando-se as informações apresentadas e os preceitos da NBC TG 47 – RECEITA DE CONTRATO COM CLIENTE, a receita deve ser reconhecida',null,'{"original": ["/cfc-2026-1/q16-1.png"]}','["quando o pagamento via PIX foi realizado, pois a contraprestação foi recebida e a nota fiscal emitida; a perda do livro deve ser reconhecida pelo cliente, que já havia quitado a compra.", "no momento do despacho da mercadoria pelo centro de distribuição, pois a empresa já cumpriu sua obrigação principal; a perda decorrente do acidente deve ser reconhecida pelo cliente.", "quando o livro for efetivamente entregue ao cliente, momento em que ocorre a transferência de controle do bem; como o acidente ocorreu antes da entrega, a perda do livro deve ser reconhecida pela própria companhia.", "no momento da emissão da nota fiscal eletrônica, pois esse ato caracteriza a transferência jurídica do bem; a perda decorrente do acidente deve ser reconhecida como despesa operacional do cliente."]'::jsonb,'C',null from public.exams where slug='cfc-2026-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,17,'Ciências Contábeis','Com base na NBC TG 06 (R3) – OPERAÇÕES DE ARRENDAMENTO MERCANTIL, assinale a opção que apresenta o procedimento correto para a contabilização de um contrato de arrendamento de uma máquina celebrado entre a arrendatária ABC e a arrendadora XYZ.',null,'{"original": ["/cfc-2026-1/q17-1.png"]}','["O ativo de direito de uso deve ser mensurado inicialmente pelo valor justo da máquina, e posteriormente pelo mesmo valor contábil de máquinas similares de propriedade da ABC.", "A empresa ABC, ao definir a vida útil para cálculo da depreciação do ativo de direito de uso, precisou definir se permanecerá ou não com a máquina permanentemente. Caso ela opte por não permanecer com a máquina ao final do contrato de arrendamento, a vida útil será a menor entre o prazo do arrendamento e a vida útil da máquina.", "O reconhecimento do ativo de direito de uso pela ABC implica a baixa do ativo imobilizado pela XYZ, para evitar duplo reconhecimento do mesmo bem.", "A depreciação do ativo de direito de uso na arrendatária ABC tem como contrapartida o passivo de arrendamento reconhecido junto à XYZ."]'::jsonb,'B',null from public.exams where slug='cfc-2026-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,18,'Ciências Contábeis','Em 2023, uma empresa de consultoria contábil pagou R$ 20.000,00 a título de juros sobre empréstimo bancário. De acordo com a NBC TG 03 (R3) – DEMONSTRAÇÃO DOS FLUXOS DE CAIXA, os juros pagos podem ser classificados, na Demonstração dos Fluxos de Caixa, como fluxos de caixa',null,'{"original": ["/cfc-2026-1/q18-1.png"]}','["operacionais ou de investimento.", "operacionais ou de financiamento.", "de investimento ou de financiamento.", "de financiamento ou de equivalentes de caixa."]'::jsonb,'B',null from public.exams where slug='cfc-2026-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,19,'Ciências Contábeis','Na geração interna de um ativo intangível por uma sociedade empresária, foram gastos R$ 10.000,00 com atividades destinadas à obtenção de novo conhecimento, R$ 15.000,00 com formulação, projeto, avaliação e seleção final de alternativas possíveis para materiais e processos, e R$ 20.000,00 com o projeto, construção e teste de protótipos e modelos pré-produção. Sabe-se que estavam presentes todos os requisitos dispostos na NBC TG 04 (R4) – ATIVO INTANGÍVEL, para o reconhecimento dos gastos incorridos na fase de desenvolvimento de um Ativo Intangível. A vida útil estimada do ativo é de 10 anos e o valor residual é zero. Considerando que a sociedade empresária utiliza o método da linha reta para amortizar os seus ativos intangíveis, a despesa de amortização anual do ativo foi de',null,'{"original": ["/cfc-2026-1/q19-1.png"]}','["R$ 0,00.", "R$ 2.000,00.", "R$ 3.500,00.", "R$ 4.500,00."]'::jsonb,'B',null from public.exams where slug='cfc-2026-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,20,'Ciências Contábeis','Uma loja de celulares utiliza o Custo Médio Ponderado móvel em base diária para valoração do estoque. Em julho de 2025, não havia estoque inicial do celular de modelo “XPTO”. No mês, houve a seguinte movimentação em relação a esse modelo de celular: • 02/07: compra de 20 unidades por R$ 3.000,00 cada; • 10/07: venda de 10 unidades por R$ 5.000,00 cada; • 15/07: compra de 15 unidades por R$ 3.200,00 cada; • 20/07: venda de 8 unidades por R$ 5.000,00 cada; • 27/07: venda de 5 unidades por R$ 5.200,00 cada. O estoque de “XPTO” da loja, em 31/07/2025, era de',null,'{"original": ["/cfc-2026-1/q20-1.png"]}','["R$ 36.988,00.", "R$ 37.200,00.", "R$ 37.440,00.", "R$ 61.200,00."]'::jsonb,'C',null from public.exams where slug='cfc-2026-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,21,'Ciências Contábeis','Em sua Demonstração do Valor Adicionado, uma sociedade empresária apresentou os seguintes saldos: • Despesas financeiras: R$ 35.000,00; • Assistência médica a empregados: R$ 80.000,00; • Aluguel: R$ 120.000,00; • Remuneração direta de empregados: R$ 240.000,00. O saldo apresentado em “Remuneração de Capitais de Terceiros”, na segunda parte da Demonstração do Valor Adicionado, de acordo com a NBC TG 09 (R1) – DEMONSTRAÇÃO DO VALOR ADICIONADO, foi de',null,'{"original": ["/cfc-2026-1/q21-1.png"]}','["R$ 155.000,00.", "R$ 235.000,00.", "R$ 320.000,00.", "R$ 475.000,00."]'::jsonb,'A',null from public.exams where slug='cfc-2026-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,22,'Ciências Contábeis','Os saldos das contas de resultado do exercício da Cia. “G” S.A. em 31/12/X2 eram os seguintes: • Despesas com tributos sobre o lucro: R$ 510.000,00; • Despesas operacionais: R$ 20.000,00; • Receita bruta de serviços: R$ 1.500.000,00; • Impostos sobre serviços: R$ 40.000,00; • Descontos incondicionais: R$ 30.000,00; • Custo dos serviços prestados: R$ 400.000,00. Com base nessas informações, é correto afirmar que a Cia. “G” S.A. apurou',null,'{"original": ["/cfc-2026-1/q22-1.png"]}','["um lucro bruto de R$ 1.050.000,00.", "uma receita líquida de serviços de R$ 1.030.000,00.", "um lucro bruto de R$ 1.010.000,00.", "um lucro líquido de R$ 500.000,00."]'::jsonb,'D',null from public.exams where slug='cfc-2026-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,23,'Ciências Contábeis','A Cia. “C” S.A. possuía, em 31/12/X1, um ativo registrado em seu imobilizado mensurado como segue: • Custo de aquisição: R$ 105.000,00; • (–) Depreciação acumulada: R$ 20.000,00; • (–) Perda por redução ao valor recuperável reconhecida em X0: R$ 10.000,00. Antes da elaboração das demonstrações contábeis, a empresa realizou o teste de recuperabilidade do ativo, apurando os seguintes valores: • Valor justo líquido de despesas de venda: R$ 80.000,00; • Valor em uso: R$ 90.000,00. Com base nos dados apresentados, é correto afirmar que',null,'{"original": ["/cfc-2026-1/q23-1.png"]}','["o valor contábil líquido do ativo, antes do ajuste da perda, é de R$ 85.000,00.", "o valor recuperável do ativo, no momento da avaliação, é de R$ 80.000,00.", "o valor recuperável do ativo, no momento da avaliação, é de R$ 90.000,00.", "a perda estimada para esse ativo é de R$ 25.000,00."]'::jsonb,'C',null from public.exams where slug='cfc-2026-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,24,'Ciências Contábeis','A empresa “A” realizou a venda de 350.000 quadros de madeira (30x40 cm), totalizando R$ 250.000,00 em mercadorias vendidas. Sabe-se que o controle das mercadorias foi imediatamente transferido aos clientes. O recebimento foi distribuído da seguinte forma: 50% em Caixa, 25% em Banco, e 25% a prazo, com vencimento em 30 dias. Com base nesses dados, assinale a opção correta quanto à contabilização dessas operações.',null,'{"original": ["/cfc-2026-1/q24-1.png"]}','["Débito: Caixa R$ 125.000,00 Débito: Banco Conta Movimento R$ 62.500,00 Débito: Duplicatas a Receber R$ 62.500,00 Crédito: Receita de Vendas R$ 250.000,00", "Débito: Caixa R$ 125.000,00 Débito: Duplicatas a Receber R$ 125.000,00 Crédito: Receita de Vendas R$ 250.000,00", "Débito: Caixa R$ 250.000,00 Crédito: Receita de Vendas R$ 250.000,00", "Débito: Caixa R$ 125.000,00 Débito: Banco R$ 125.000,00 Crédito: Receita de Vendas R$ 250.000,00"]'::jsonb,'A',null from public.exams where slug='cfc-2026-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,25,'Ciências Contábeis','Em 01/07/2025, uma construtora iniciou a construção de um prédio formado por estúdios de 20 metros quadrados. O prazo estimado para a construção era de 18 meses. Nos primeiros três meses de obra, os gastos diretos, associados à construção, foram de R$ 500.000,00. Em 30/09/2025, um grupo de moradores entrou na Justiça contra a construtora para solicitar a suspensão da obra, já que consideravam que o tipo de apartamento seria prejudicial ao bairro. Além disso, pediam uma indenização de R$ 200.000,00. Na data, os advogados da construtora julgaram que perda da causa era possível. Ainda, por determinação da justiça, a obra foi suspensa e não havia sido retomada até 31/12/2025. Por conta do processo, com base na NBC TG 25 (R2) – PROVISÕES, PASSIVOS CONTINGENTES E ATIVOS CONTINGENTES, no Balanço Patrimonial da construtora, em 31/12/2025,',null,'{"original": ["/cfc-2026-1/q25-1.png"]}','["houve uma provisão para contingências de R$ 200.000,00.", "houve uma provisão para contingências de R$ 500.000,00.", "houve uma provisão para contingências de R$ 700.000,00.", "não houve impacto nos elementos patrimoniais."]'::jsonb,'D',null from public.exams where slug='cfc-2026-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,26,'Ciências Contábeis','Uma sociedade empresária apresentava a sua Demonstração dos Fluxos de Caixa de acordo com o método direto. Em 01/01/2025, resolveu começar a apresentar a demonstração de acordo com o método indireto. Desse modo, em 31/12/2025, a sociedade empresária divulgou a Demonstração dos Fluxos de Caixa de 31/12/2024, elaborada de acordo com o método indireto, para fins comparativos. Pôde-se constatar, a partir da demonstração, que as atividades operacional, de investimento e de financiamento geraram caixa para a sociedade empresária. Ao comparar o saldo de caixa gerado pelas três atividades na Demonstração dos Fluxos de Caixa, referente a 31/12/2024, de acordo com o método direto e indireto, pode-se verificar que',null,'{"original": ["/cfc-2026-1/q26-1.png"]}','["o saldo de caixa gerado pelas três atividades permanece igual.", "o saldo de caixa apresentado pelas três atividades apresenta mudança.", "apenas o saldo de caixa gerado pela atividade operacional apresenta mudança.", "apenas o saldo de caixa gerado pela atividade de financiamento apresenta mudança."]'::jsonb,'A',null from public.exams where slug='cfc-2026-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,27,'Ciências Contábeis','Em 31/12/2025, a Cia. “X” e a Cia. “Y” apresentavam os seguintes saldos em seus Balanços Patrimoniais: • Cia “X”: Disponibilidades: R$ 80.000,00; Patrimônio Líquido: R$ 80.000,00; • Cia “Y”: Disponibilidades: R$ 40.000,00; Patrimônio Líquido: R$ 40.000,00. Sabe-se que os valores contábeis dos ativos líquidos das Cias. “X” e “Y” correspondem aos respectivos valores justos nessa data. Em 01/01/2026, a Cia. “X” adquiriu 90% da Cia. “Y” por R$ 42.000,00, à vista. A diferença entre o valor pago e o valor contábil foi atribuída à capacidade de geração de benefícios econômicos futuros. Assinale a opção que indica o saldo do Ativo Circulante no Balanço Patrimonial Consolidado após a compra.',null,'{"original": ["/cfc-2026-1/q27-1.png"]}','["R$ 38.000,00.", "R$ 74.000,00.", "R$ 75.800,00.", "R$ 78.000,00."]'::jsonb,'D',null from public.exams where slug='cfc-2026-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,28,'Ciências Contábeis','Ao preparar o encerramento do exercício, o setor de Contabilidade da companhia “B” S.A. listou as seguintes contas e seus respectivos saldos: 1. Adiantamento a fornecedor: R$ 12.000,00; 2. Adiantamento de clientes: R$ 8.000,00; 3. Encargos financeiros a transcorrer (sobre empréstimos bancários obtidos): R$ 3.500,00; 4. Ações de emissão própria em tesouraria: R$ 5.000,00; 5. Juros sobre o capital próprio a pagar: R$ 4.500,00; 6. Perdas estimadas com créditos de liquidação duvidosa: R$ 2.000,00. Assinale a opção que indica o somatório correto, em valores absolutos, das contas de natureza devedora.',null,'{"original": ["/cfc-2026-1/q28-1.png"]}','["R$ 20.500,00.", "R$ 15.500,00.", "R$ 12.000,00.", "R$ 20.000,00."]'::jsonb,'A',null from public.exams where slug='cfc-2026-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,29,'Ciências Contábeis','Uma empresa varejista adquiriu mercadoria à vista para revenda no curto prazo. Os dados relacionados a essa compra são: • Valor unitário: R$ 200,00; • Quantidade adquirida: 1.000 unidades; • Imposto de importação: R$ 10,00/unidade (por fora do preço de aquisição); • Seguro: R$ 6.000,00; • Transporte da mercadoria: R$ 4.000,00; • Imposto de circulação de mercadorias (ICMS): R$ 20,00/unidade (embutido no preço de aquisição); • Desconto comercial: R$ 15,00/unidade. Considerando o ICMS como um tributo não recuperável pela empresa adquirente, e com base exclusivamente nos dados apresentados, o custo total do estoque adquirido é de',null,'{"original": ["/cfc-2026-1/q29-1.png"]}','["R$ 205.000,00.", "R$ 210.000,00.", "R$ 220.000,00.", "R$ 235.000,00."]'::jsonb,'A',null from public.exams where slug='cfc-2026-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,30,'Ciências Contábeis','A empresa Alfa S.A. possui 70% de participação em Beta S.A., adquirida por R$ 5.000.000,00. No final do exercício atual, Beta S.A. apurou um lucro líquido de R$ 1.000.000,00, destinado da seguinte forma: R$ 800.000,00 para a constituição de reservas e R$ 200.000,00 para ser distribuído na forma de dividendos. Com base exclusivamente nas informações apresentadas, o valor de ganho com equivalência patrimonial, a ser reconhecido no resultado do exercício da empresa Alfa S.A., deverá ser de',null,'{"original": ["/cfc-2026-1/q30-1.png"]}','["R$ 140.000,00.", "R$ 560.000,00.", "R$ 700.000,00.", "R$ 3.500.000,00."]'::jsonb,'C',null from public.exams where slug='cfc-2026-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,31,'Ciências Contábeis','A cidade Alfa foi atingida por uma enchente nos meses de janeiro e fevereiro de X6, afetando diversas empresas da região. Entre elas, a Metalúrgica “M” Ltda. sofreu perdas significativas, com a inutilização de 25% de seus estoques. No tratamento contábil a ser adotado pela Metalúrgica “M” Ltda. para o reconhecimento desse evento em sua contabilidade, essa perda deve ser reconhecida como',null,'{"original": ["/cfc-2026-1/q31-1.png"]}','["Custo da Mercadoria Vendida (CMV), uma vez que impacta diretamente o volume de estoques disponíveis para venda.", "despesa operacional (perdas por sinistro/enchente), sem necessidade de ajuste no saldo de estoques, tendo em vista a ausência de expectativa de recuperação dos itens.", "normal no curso das operações da entidade, devendo ser apropriada ao resultado como custo, diluído entre as unidades produzidas.", "despesa (perdas por sinistro/enchente), com a correspondente baixa no saldo de estoques, em função da inutilização dos bens e da ausência de expectativa de recuperação econômica."]'::jsonb,'D',null from public.exams where slug='cfc-2026-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,32,'Ciências Contábeis','Uma empresa possuía, em seu ativo imobilizado, um prédio, classificado como de uso administrativo. O valor de custo desse ativo era R$ 500.000,00, sua vida útil estimada era de 20 anos e seu valor residual era R$ 100.000,00. Após 5 anos, no dia 05/01/2025, a empresa classificou esse prédio como ativo não circulante mantido para venda, pois concluiu que o seu valor contábil seria recuperado, principalmente, por meio de transação de venda em vez do uso contínuo. Além disso, todos os requisitos da NBC TG 31 (R4) – ATIVO NÃO CIRCULANTE MANTIDO PARA VENDA E OPERAÇÃO DESCONTINUADA haviam sido cumpridos para essa classificação. No entanto, um ano após a classificação, no dia 05/01/2026, a empresa desistiu da venda e voltou a classificar o prédio como seu ativo imobilizado. O contador apurou adicionalmente as seguintes informações: • Valor justo do prédio em 05/01/2025: R$ 500.000,00; • Despesas de vendas em 05/01/2025: R$ 50.000,00; • Valor em uso do prédio em 05/01/2025: R$ 300.000,00; • Valor justo do prédio em 05/01/2026: R$ 450.000,00; • Despesas de vendas em 05/01/2026: R$ 45.000,00; • Valor em uso do prédio em 05/01/2026: R$ 420.000,00. Com base exclusivamente nos dados apresentados, a empresa deve mensurar o prédio na classificação como ativo imobilizado em 05/01/2026 pelo seguinte valor:',null,'{"original": ["/cfc-2026-1/q32-1.png"]}','["R$ 380.000,00.", "R$ 405.000,00.", "R$ 420.000,00.", "R$ 450.000,00."]'::jsonb,'A',null from public.exams where slug='cfc-2026-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,33,'Ciências Contábeis','Para aplicação do método de equivalência patrimonial, quando se trata de investimentos em investidas com influência significativa, a NBC TG 18 (R4) – INVESTIMENTO EM COLIGADA E EM EMPREENDIMENTO CONTROLADO EM CONJUNTO traz algumas situações em que se poderia considerar que a investidora detém uma influência significativa. Analise as seguintes afirmativas acerca de influência significativa: I. Presume-se que a investidora tenha influência significativa sobre a investida se detiver, direta ou indiretamente, 20% ou mais do poder de voto da investida, a menos que possa ser claramente demonstrado o contrário. II. Caso a investidora detenha menos de 20% do poder de voto da investida, não é admissível supor influência significativa, em nenhuma hipótese. III. A representação, no Conselho de Administração ou na diretoria da investida pela investidora, pode ser uma evidência de influência significativa da entidade investidora na investida. Está correto o que se afirma em',null,'{"original": ["/cfc-2026-1/q33-1.png"]}','["I, apenas.", "II e III, apenas.", "I, II e III.", "I e III, apenas."]'::jsonb,'D',null from public.exams where slug='cfc-2026-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,34,'Ciências Contábeis','Uma companhia S.A., concessionária de serviços públicos, emitiu faturas a prazo no valor total de R$ 100.000,00, com vencimento em 12 meses. Em conformidade com a NBC TG 12 (R1) – AJUSTE A VALOR PRESENTE, a empresa calculou um ajuste a valor presente relevante e com efeito material de R$ 5.000,00, representando os juros embutidos no prazo das faturas. Considerando as informações apresentadas e os preceitos da NBC TG 12 (R1) – AJUSTE A VALOR PRESENTE, o lançamento contábil, no momento do reconhecimento da receita, é',null,'{"original": ["/cfc-2026-1/q34-1.png"]}','["Débito: Clientes R$ 100.000,00 Crédito: Receita de Serviços R$ 100.000,00", "Débito: Clientes R$ 95.000,00 Crédito: Receita Financeira a Apropriar R$ 5.000,00 Crédito: Receita de Serviços R$ 100.000,00", "Débito: Clientes R$ 95.000,00 Débito: Juros a Apropriar R$ 5.000,00 Crédito: Receita de Serviços R$ 100.000,00", "Débito: Clientes R$ 100.000,00 Crédito: Receita de Serviços R$ 95.000,00 Crédito: Juros a Apropriar R$ 5.000,00"]'::jsonb,'D',null from public.exams where slug='cfc-2026-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,35,'Ciências Contábeis','A Indústria “M” S.A. produz itens para cabelos crespos e cacheados. Ela utiliza como parâmetro de análise e tomada de decisão de custo, o custo padrão e o custo real. No mês de junho de 2024, ela apresentou os seguintes dados: Custo Padrão Custo Real Descrição Quantidade Custo Unitário Custo Total Quantidade Custo Unitário Custo Total Tensoativos 3,00 45,00 135,00 4,50 55,00 247,50 Óleo de Argan 6,00 6,55 39,30 9,00 5,47 49,30 Estabilizantes de espuma 255,00 0,15 38,25 127,50 0,11 14,03 Espessantes 56,00 0,10 5,60 28,00 0,50 14,00 A partir desses dados, em relação à variação dos itens dos insumos de produção da Indústria “M” S.A., é correto afirmar que',null,'{"original": ["/cfc-2026-1/q35-1.png"]}','["o Óleo de Argan apresentou variações favoráveis para a Indústria “M” S.A..", "os Estabilizantes de espuma apresentam variações favoráveis para a Indústria “M” S.A..", "as variações de custo total do Estabilizantes de espuma e do Espessantes são desfavoráveis.", "as variações de custo total dos Tensoativos e do Óleo de Argan são favoráveis."]'::jsonb,'B',null from public.exams where slug='cfc-2026-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,36,'Ciências Contábeis','Uma renomada empresa de fabricação de violinos para orquestra, a Violinos “K”, iniciou suas operações no mês de janeiro. Seu único violino produzido é vendido por R$ 2.000,00 cada. Em janeiro de X4, a empresa produziu 1.200 unidades e vendeu 900 unidades. Os custos variáveis no período totalizaram R$ 600,00 por violino. Os custos fixos e despesas fixas mensais da empresa foram os seguintes: • Salários dos supervisores de fábrica: R$ 150.000,00 por mês; • Salários do pessoal administrativo: R$ 30.000,00 por mês; • Depreciação das máquinas utilizadas na fabricação: R$ 39.800,00 por mês; • Aluguel do prédio da fábrica: R$ 15.000,00 por mês; • Custos diversos de manufatura: R$ 10.000,00 por mês; • Promoção e Propaganda: R$ 20.000,00 por mês. Não houve estoques de produtos em elaboração, e não são considerados tributos incidentes sobre a receita. Assinale a opção que indica o Lucro Bruto da empresa pelo método de custeio por absorção.',null,'{"original": ["/cfc-2026-1/q36-1.png"]}','["R$ 1.061.397,00.", "R$ 1.465.200,00.", "R$ 1.045.200,00.", "R$ 1.098.900,00."]'::jsonb,'D',null from public.exams where slug='cfc-2026-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,37,'Ciências Contábeis','A companhia Indústria “K” S.A. possui, em sua planta de fábrica, os setores de Montagem (30 m²) e Acabamento (50 m²). Em determinado período, o custo com a energia elétrica da produção foi de R$ 25.000,00. O critério de rateio adotado pela empresa é por área ocupada. Sendo assim, o valor alocado ao setor de Montagem é de',null,'{"original": ["/cfc-2026-1/q37-1.png"]}','["R$ 15.625,00.", "R$ 9.375,00.", "R$ 12.500,00.", "R$ 10.000,00."]'::jsonb,'B',null from public.exams where slug='cfc-2026-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,38,'Ciências Contábeis','A seguir, encontram-se alguns dos eventos da Indústria J em um determinado período: • Consumo da matéria-prima X: R$ 17.900,00; • Depreciação do prédio do escritório: R$ 6.600,00; • Compra da matéria-prima X: R$ 100.000,00; • Depreciação das máquinas do parque fabril: R$ 8.500,00; • Remuneração dos funcionários do Faturamento (salários): R$ 23.000,00; • Aquisição da máquina XFG210 para o parque fabril: R$ 149.000,00. Assinale a opção que apresenta os valores corretos de Custos, Despesas e Investimentos, de acordo com a terminologia contábil.',null,'{"original": ["/cfc-2026-1/q38-1.png"]}','["Custos: R$ 126.400,00; Despesas: R$ 29.600,00; Investimentos: R$ 149.000,00.", "Custos: R$ 26.400,00; Despesas: R$ 29.600,00; Investimentos: R$ 249.000,00.", "Custos: R$ 26.400,00; Despesas: R$ 52.600,00; Investimentos: R$ 149.000,00.", "Custos: R$ 35.100,00; Despesas: R$ 29.600,00; Investimentos: R$ 228.000,00."]'::jsonb,'B',null from public.exams where slug='cfc-2026-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,39,'Ciências Contábeis','Analise as informações abaixo sobre a empresa “N” S.A.: • Ativo circulante: R$ 1.000.000,00; • Ativo total: R$ 1.800.000,00; • Passivo não circulante: R$ 400.000,00; • Índice de liquidez seca: 0,50; • Estoque médio de mercadorias: R$ 400.000,00. Com base nos dados, o valor do patrimônio líquido dessa empresa é de',null,'{"original": ["/cfc-2026-1/q39-1.png"]}','["R$ 200.000,00.", "R$ 400.000,00.", "R$ 1.200.000,00.", "R$ 1.600.000,00."]'::jsonb,'A/B/C/D/E',null from public.exams where slug='cfc-2026-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,40,'Ciências Contábeis','Uma empresa fornece componentes tecnológicos para outras indústrias. Essa empresa adquire sua matéria-prima sempre a prazo, com pagamento médio em 20 dias. Em média, a empresa leva 70 dias para fabricar, armazenar e vender seus produtos. Ela vende somente a prazo, com pagamento em até 90 dias após a venda e, em média, leva 80 dias para receber após as vendas. Com base exclusivamente nesses dados, o ciclo operacional dessa empresa é de',null,'{"original": ["/cfc-2026-1/q40-1.png"]}','["70 dias.", "90 dias.", "150 dias.", "160 dias."]'::jsonb,'C',null from public.exams where slug='cfc-2026-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,41,'Ciências Contábeis','Uma joalheria vende relógios por R$ 300,00 cada. O custo variável do relógio é de R$ 170,00, e o ponto de equilíbrio contábil da loja é de 500 unidades. Os administradores da loja decidiram aumentar o preço dos relógios para R$ 330,00, a partir do segundo semestre de 2026. Considerando que os custos fixos e variáveis permanecerão iguais, o ponto de equilíbrio da loja, após esse aumento, será de',null,'{"original": ["/cfc-2026-1/q41-1.png"]}','["407 unidades.", "455 unidades.", "475 unidades.", "550 unidades."]'::jsonb,'A',null from public.exams where slug='cfc-2026-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,42,'Ciências Contábeis','Uma empresa estimou os níveis de atividade para o exercício seguinte e calculou seus prazos médios correspondentes. Os resultados estão apresentados a seguir: • Receitas com vendas a prazo: R$ 250.000,00; • Custo dos produtos vendidos: R$ 110.000,00; • Aquisição de matéria-prima a prazo: R$ 90.000,00; • Demais despesas operacionais: R$ 30.000,00; • Prazo médio de contas a receber: 38 dias; • Prazo médio dos estoques: 32 dias; • Prazo médio de contas a pagar: 34 dias; • Prazo médio de demais despesas operacionais a pagar: 22 dias. Com base exclusivamente nos dados apresentados, a necessidade de capital de giro dessa empresa é de',null,'{"original": ["/cfc-2026-1/q42-1.png"]}','["R$ 25.479,00.", "R$ 26.027,00.", "R$ 27.287,00.", "R$ 35.671,00."]'::jsonb,'A',null from public.exams where slug='cfc-2026-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,43,'Ciências Contábeis','Em uma entidade do setor público, verificou-se que o empenho, que havia sido formalizado, foi anulado parcialmente. Um possível motivo para a anulação parcial do empenho é que',null,'{"original": ["/cfc-2026-1/q43-1.png"]}','["o objeto do contrato não foi cumprido.", "a nota de empenho foi emitida de modo incorreto.", "o valor do empenho excedia o montante da despesa realizada.", "o valor empenhado era insuficiente para atender à despesa a ser realizada."]'::jsonb,'C',null from public.exams where slug='cfc-2026-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,44,'Ciências Contábeis','À luz do disposto no Manual de Contabilidade Aplicada ao Setor Público (MCASP), quanto ao reconhecimento e à mensuração de ativos da concessão de serviços públicos, avalie as afirmativas a seguir. I. A mensuração inicial dos ativos da concessão deve ser realizada pelo menor valor entre o custo histórico e o valor recuperável. II. Quando o concedente não controla nem regula os serviços objeto da concessão, o ativo da concessão não deve ser por ele reconhecido. III. Os ativos da concessão devem ser classificados nas contas patrimoniais de ativo intangível, sem necessidade de segregação em classes. IV. Os ativos da concessão estão sujeitos à depreciação, reavaliação e redução a valor recuperável, quando aplicáveis, como os demais itens do ativo imobilizado. Estão corretas apenas as afirmativas',null,'{"original": ["/cfc-2026-1/q44-1.png"]}','["I e IV.", "III e IV.", "II e III.", "II e IV."]'::jsonb,'D',null from public.exams where slug='cfc-2026-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,45,'Ciências Contábeis','Durante a elaboração da Lei Orçamentária Anual (LOA), um determinado governo estadual decidiu incluir no orçamento receitas provenientes de um novo tributo, cuja criação ainda dependia de aprovação legislativa e regulamentação posterior. À luz dos princípios orçamentários aplicáveis ao setor público brasileiro, essa prática viola, principalmente, o princípio da',null,'{"original": ["/cfc-2026-1/q45-1.png"]}','["universalidade.", "exclusividade.", "legalidade.", "anualidade."]'::jsonb,'C',null from public.exams where slug='cfc-2026-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,46,'Ciências Contábeis','Em uma organização contábil, o contador responsável definiu diretrizes gerais para qualidade e conformidade profissional; os gestores traduziram essas diretrizes em metas por setor; e a equipe executou rotinas diárias de escrituração e atendimento às exigências do CRC. Considerando a aplicação dos níveis de planejamento no exercício da profissão contábil, conforme a NBC PG 01 – CÓDIGO DE ÉTICA PROFISSIONAL DO CONTADOR e a NBC PG 100 (R1) – CUMPRIMENTO DO CÓDIGO, DOS PRINCÍPIOS FUNDAMENTAIS E DA ESTRUTURA CONCEITUAL, associe corretamente os tipos de planejamento a seguir a suas respectivas descrições: 1. Planejamento estratégico. 2. Planejamento tático. 3. Planejamento operacional. I. Execução das rotinas diárias e procedimentos técnicos. II. Definição de diretrizes gerais e objetivos de longo prazo. III. Desdobramento das diretrizes em metas e ações setoriais. A correspondência correta é',null,'{"original": ["/cfc-2026-1/q46-1.png"]}','["1–III; 2–II; 3–I.", "1–I; 2–III; 3–II.", "1–II; 2–I; 3–III.", "1–II; 2–III; 3–I."]'::jsonb,'D',null from public.exams where slug='cfc-2026-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,47,'Ciências Contábeis','Durante a execução dos trabalhos de campo de auditoria das demonstrações financeiras de uma empresa de médio porte, um Auditor, ao revisar os lançamentos contábeis no sistema de gestão, identificou diversas transações de vendas que não tinham respaldo em contratos ou faturas válidas. Aplicando os procedimentos previstos na norma de auditoria correspondente, que trata da responsabilidade do auditor em relação à fraude na auditoria de demonstrações contábeis, o Auditor aprofundou a investigação e constatou que um funcionário do setor financeiro havia registrado vendas fictícias para inflar as receitas da empresa, o que caracterizava fraude com a intenção de manipular os resultados financeiros. Frente à gravidade da situação, o Auditor deve, imediatamente,',null,'{"original": ["/cfc-2026-1/q47-1.png"]}','["procurar a ajuda de especialistas.", "renunciar ao trabalho.", "fazer uma denúncia anônima para a Polícia Federal.", "relatar ao Conselho de Administração."]'::jsonb,'D',null from public.exams where slug='cfc-2026-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,48,'Ciências Contábeis','Em um treinamento para novos auditores, o instrutor destacou que, mesmo após a execução adequada dos procedimentos, pode haver a emissão de uma opinião inadequada sobre as demonstrações contábeis. Esse cenário representa o conceito de risco de auditoria, que pode ser definido como',null,'{"original": ["/cfc-2026-1/q48-1.png"]}','["julgamento técnico realizado com base na experiência do auditor, sujeito a diferentes interpretações.", "erro natural ocorrido durante o processo contábil, sem intenção da administração, mas que afeta o resultado final.", "probabilidade de falha nos procedimentos ou controles, levando a conclusões incorretas sobre as demonstrações contábeis.", "possibilidade de o auditor emitir uma opinião inadequada sobre demonstrações contábeis que contenham distorções relevantes não detectadas."]'::jsonb,'D',null from public.exams where slug='cfc-2026-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,49,'Ciências Contábeis','Um empregado foi admitido em 01/03/2021 e trabalhou até 31/03/2023. O salário mensal dele era de R$ 3.600,00. Durante o período trabalhado, o empregado gozou de 15 dias de férias e o restante dos dias foi acumulado como férias proporcionais. O adicional de 1/3 sobre as férias é aplicável. Com base nessas informações, o laudo do perito deve apresentar que precisa ser pago ao empregado, referente ao saldo de férias proporcionais ao término do contrato e incluindo o adicional de 1/3 (considere para as contas os meses com 30 dias), o valor igual a',null,'{"original": ["/cfc-2026-1/q49-1.png"]}','["R$ 4.800,00.", "R$ 5.200,00.", "R$ 6.780,00.", "R$ 7.600,00."]'::jsonb,'D',null from public.exams where slug='cfc-2026-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,50,'Ciências Contábeis','O contador “X” foi nomeado para atuar como perito contábil em âmbito judicial. O juiz “Y” definiu o prazo para entrega do laudo em 30 dias úteis. Apesar da pronta aceitação do contador “X”, ao longo do exercício da função nesse caso, uma série de dificuldades técnicas fez com que o prazo inicialmente disposto para a entrega do laudo se mostrasse inviável. Assim, o contador “X” solicitou a prorrogação do prazo ao juiz “Y”. De acordo com o Novo Código de Processo Civil (CPC/2015), é correto afirmar que o juiz “Y”',null,'{"original": ["/cfc-2026-1/q50-1.png"]}','["poderá conceder, por uma vez, a prorrogação de mais 30 dias úteis, se lhe for apresentado um motivo justificado.", "deverá conceder, por uma vez, a prorrogação de mais 15 dias úteis, se lhe for apresentado um motivo justificado.", "deverá conceder, por uma vez, a prorrogação de mais 30 dias úteis, se lhe for apresentado um motivo justificado.", "poderá conceder, por uma vez, a prorrogação de mais 15 dias úteis, se lhe for apresentado um motivo justificado."]'::jsonb,'D',null from public.exams where slug='cfc-2026-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.exams(slug,title,source,year) values ('cfc-2025-2','CFC 2025.2 — Exame de Suficiência — Contador — Tipo 1','cfc','2025') on conflict(slug) do update set title=excluded.title,source=excluded.source,year=excluded.year;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,1,'Língua Portuguesa','Os dicionários registram os diversos significados de um vocábulo; os dois textos abaixo definem o termo “contabilidade”, segundo, respectivamente, os dicionários de Antônio Houaiss (AH) e de Aurélio Buarque de Hollanda (ABH). (AH) Contabilidade: ciência teórica e prática que estuda os métodos de cálculo e registro da movimentação financeira de uma firma ou empresa. (ABH) Contabilidade: ciência que estuda e interpreta os registros dos fenômenos que afetam o patrimônio de uma entidade (empresa, instituição pública, pessoa física, instituição não lucrativa etc.). Sobre esses textos, assinale a afirmativa correta.',null,'{"original": ["/cfc-2025-2/q1-1.png"]}','["As definições começam sempre por uma palavra de conteúdo geral que, nesses casos, é representada pela palavra “ciência”.", "Os termos “teórica e prática” e “cálculo e registro” são construídos com palavras antônimas, ou seja, de significados opostos.", "Os termos entre parênteses da segunda definição mostram todos os tipos de entidades referidas na definição.", "As duas definições mostram o mesmo objetivo da ciência “contabilidade”."]'::jsonb,'A',null from public.exams where slug='cfc-2025-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,2,'Língua Portuguesa','As frases listadas nas opções a seguir foram reescritas de forma a eliminar-se o “que”, com substituição do verbo por um substantivo semanticamente correlato. Assinale a frase em que a substituição foi feita de forma adequada.',null,'{"original": ["/cfc-2025-2/q2-1.png"]}','["Cabral, que descobriu o Brasil, merece homenagens. / Cabral, o criador do Brasil, merece homenagens.", "Caminha, que escreveu a carta, registrou o fato. / Caminha, o redator da carta, registrou o fato.", "As caravelas, que atravessaram o oceano, resistiram a tempestades. / As caravelas, navegadoras do oceano, resistiram a tempestades.", "A descoberta do Brasil, que ocorreu em 1500, ficou na história. / A descoberta do Brasil, ocorrente em 1500, ficou na história."]'::jsonb,'B',null from public.exams where slug='cfc-2025-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,3,'Matemática Financeira e Estatística','A empresa Gama S.A. avalia um projeto com investimento inicial de R$ 300.000,00, a ser realizado na data zero. Estimam-se entradas de caixa ao final de cada ano, conforme segue: • 1º ano: R$ 121.000,00; • 2º ano: R$ 121.000,00; • 3º ano em diante: R$ 146.410,00 por ano. Chama-se payback descontado ao tempo necessário para que a soma dos fluxos de caixa descontados iguale o investimento inicial. Considerando-se uma taxa de desconto de 10% ao ano, o payback do projeto está entre',null,'{"original": ["/cfc-2025-2/q3-1.png"]}','["1 ano e 2 anos.", "2 anos e 3 anos.", "3 anos e 4 anos.", "4 anos e 5 anos."]'::jsonb,'B',null from public.exams where slug='cfc-2025-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,4,'Matemática Financeira e Estatística','A empresa VGF S.A. tomou um empréstimo bancário de R$ 14.560,00 para financiar a compra de equipamentos. O contrato de empréstimo estabelece que o valor tomado deve ser liquidado por meio de uma série postecipada de 3 pagamentos mensais, iguais e sucessivos. O regime de capitalização adotado é o de juros compostos, à taxa de 20% ao mês. Considerando essas informações, é correto afirmar que o valor das prestações mensais será de',null,'{"original": ["/cfc-2025-2/q4-1.png"]}','["R$ 4.853,33.", "R$ 6.400,00.", "R$ 6.912,00.", "R$ 7.280,00."]'::jsonb,'C',null from public.exams where slug='cfc-2025-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,5,'Ciências Contábeis','Para o contador que atua no setor público ou na fiscalização de contratos administrativos, o conhecimento da Lei nº 14.133, de 1º de abril de 2021 (Lei de Licitações e Contratos), é fundamental para a avaliação da legalidade e conformidade dos gastos públicos. O Art. 5º dessa Lei elenca diversos princípios que devem guiar a atuação das Administrações Públicas diretas, autárquicas e fundacionais da União, dos Estados, do Distrito Federal e dos Municípios. Com base no texto legal, avalie os seguintes princípios: I. Impessoalidade; II. Transparência; III. Racionalidade econômica; IV. Probidade administrativa. Estão expressamente listados no Art. 5º da Lei os princípios',null,'{"original": ["/cfc-2025-2/q5-1.png"]}','["I e IV, apenas.", "II e III, apenas.", "I, II e IV, apenas.", "I, II, III e IV."]'::jsonb,'C',null from public.exams where slug='cfc-2025-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,6,'Ciências Contábeis','Um estudante de contabilidade, ao iniciar seus estudos em Direito Tributário, depara-se com o conceito fundamental de tributo. Para uma compreensão precisa, ele busca a definição legal contida no Código Tributário Nacional (Lei nº 5.172/1966). De acordo com esse diploma legal, assinale a opção que define corretamente o tributo.',null,'{"original": ["/cfc-2025-2/q6-1.png"]}','["Tributo é toda prestação pecuniária voluntária, em moeda ou cujo valor nela se possa exprimir, que não constitua sanção de ato ilícito, instituída por meio de medida provisória e cobrada mediante atividade administrativa com alguma discricionariedade.", "Tributo é toda sanção de ato ilícito, cobrada compulsoriamente em bens ou serviços, instituída em lei e aplicada com base em decisões discricionárias da administração pública.", "Tributo é toda prestação pecuniária compulsória, em bens ou cujo valor nela se possa exprimir, que não constitua sanção de ato ilícito, instituída por qualquer ato normativo e cobrada mediante atividade administrativa parcialmente vinculada.", "Tributo é toda prestação pecuniária compulsória, em moeda ou cujo valor nela se possa exprimir, que não constitua sanção de ato ilícito, instituída em lei e cobrada mediante atividade administrativa plenamente vinculada."]'::jsonb,'D',null from public.exams where slug='cfc-2025-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,7,'Ciências Contábeis','De acordo com a Lei Complementar nº 123, de 14 de dezembro de 2006, que institui o Estatuto Nacional da Microempresa e da Empresa de Pequeno Porte, os limites de receita bruta anual para fins de enquadramento são informações essenciais para a atuação do contador. Considerando o que a lei estabelece sobre a definição de Microempresa (ME) e Empresa de Pequeno Porte (EPP), assinale a afirmativa correta.',null,'{"original": ["/cfc-2025-2/q7-1.png"]}','["Uma Microempresa (ME) aufere, em cada ano-calendário, receita bruta igual ou inferior a R$ 120.000,00, e uma Empresa de Pequeno Porte (EPP) aufere receita bruta superior a R$ 120.000,00 e igual ou inferior a R$ 1.200.000,00.", "Uma Microempresa (ME) aufere, em cada ano-calendário, receita bruta igual ou inferior a R$ 360.000,00, e uma Empresa de Pequeno Porte (EPP) aufere receita bruta superior a R$ 360.000,00 e igual ou inferior a R$ 4.800.000,00.", "Uma Microempresa (ME) aufere, em cada ano-calendário, receita bruta igual ou inferior a R$ 81.000,00, e uma Empresa de Pequeno Porte (EPP) aufere receita bruta superior a R$ 81.000,00 e igual ou inferior a R$ 4.800.000,00.", "Os limites de receita bruta para ME e EPP são fixados anualmente por decreto do Comitê Gestor do Simples Nacional."]'::jsonb,'B',null from public.exams where slug='cfc-2025-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,8,'Ciências Contábeis','Um escritório contábil quer expandir sua clientela com campanha de marketing, mas tem dúvidas sobre publicidade e preços conforme o Código de Ética. Com base na NBC PG 01 – CÓDIGO DE ÉTICA PROFISSIONAL DO CONTADOR, uma prática de divulgação e precificação eticamente correta é',null,'{"original": ["/cfc-2025-2/q8-1.png"]}','["prometer redução garantida de tributos sem embasamento técnico.", "comparar preços e criticar concorrentes.", "divulgar clientes e faturamento sem autorização.", "expor conhecimento técnico com artigos e estudos de caso."]'::jsonb,'D',null from public.exams where slug='cfc-2025-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,9,'Ciências Contábeis','Durante uma reunião com a diretoria de uma empresa cliente, o contador responsável apresentou os impactos financeiros de um novo contrato. Embora os dados estivessem tecnicamente corretos, os gestores demonstraram dúvidas e certa dificuldade em compreender a apresentação. Nesse cenário, a habilidade profissional que contribuiria para que o contador fosse mais eficaz, de acordo com a NBC PG 100 (R1) - CUMPRIMENTO DO CÓDIGO, DOS PRINCÍPIOS FUNDAMENTAIS E DA ESTRUTURA CONCEITUAL, seria',null,'{"original": ["/cfc-2025-2/q9-1.png"]}','["realizar escuta ativa.", "demonstrar clareza na exposição de dados.", "revisar a legislação aplicável.", "ignorar as dúvidas do cliente."]'::jsonb,'B',null from public.exams where slug='cfc-2025-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,10,'Ciências Contábeis','De acordo com a NBC TG ESTRUTURA CONCEITUAL - ESTRUTURA CONCEITUAL PARA RELATÓRIO FINANCEIRO, as características qualitativas fundamentais são relevância e representação fidedigna, sendo que, para ser representação fidedigna, a representação deve ser completa, neutra e isenta de erros. Uma informação neutra pode',null,'{"original": ["/cfc-2025-2/q10-1.png"]}','["ser parcial.", "ser prudente.", "possuir inclinações.", "ser tendenciosa na seleção de informações financeiras."]'::jsonb,'B',null from public.exams where slug='cfc-2025-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,11,'Ciências Contábeis','De acordo com a NBC TG ESTRUTURA CONCEITUAL - ESTRUTURA CONCEITUAL PARA RELATÓRIO FINANCEIRO, para ajudar os usuários das demonstrações contábeis a identificar e avaliar mudanças e tendências, as demonstrações contábeis',null,'{"original": ["/cfc-2025-2/q11-1.png"]}','["são elaboradas com base na forma jurídica, em detrimento da essência das transações.", "restringem a utilização de estimativas a casos em que poderá haver perdas financeiras do usuário.", "incluem, apenas, informações que podem ser compreendidas, também, por usuários com pouco conhecimento das atividades comerciais e econômicas, sem auxílio de consultores.", "fornecem informações comparativas de, pelo menos, um período de relatório anterior."]'::jsonb,'D',null from public.exams where slug='cfc-2025-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,12,'Ciências Contábeis','Uma sociedade empresária presta serviços de perícia a terceiros. Em junho de 2024, aconteceram os seguintes fatos: • Compra de material de escritório para pagamento em 60 dias: R$ 5.000,00; • Recebimento antecipado pelos serviços que serão prestados no segundo semestre: R$ 10.000,00; • Reconhecimento do salário de seus empregados, para pagamento em 5 de julho: R$ 12.000,00. Em junho de 2024, o passivo da sociedade empresária aumentou em',null,'{"original": ["/cfc-2025-2/q12-1.png"]}','["R$ 15.000,00.", "R$ 17.000,00.", "R$ 22.000,00.", "R$ 27.000,00."]'::jsonb,'D',null from public.exams where slug='cfc-2025-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,13,'Ciências Contábeis','De acordo com a NBC TG ESTRUTURA CONCEITUAL - ESTRUTURA CONCEITUAL PARA RELATÓRIO FINANCEIRO, com relação às implicações das características qualitativas para a escolha da base de mensuração, avalie as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) Utilizar consistentemente as mesmas bases de mensuração para os mesmos itens, seja de período a período, na entidade que reporta ou em um único período para diferentes entidades, prejudica a comparabilidade das demonstrações. ( ) A mudança na base de mensuração pode tornar as demonstrações contábeis menos compreensíveis. Contudo, a mudança pode ser justificada se outros fatores compensarem a redução na compreensibilidade, por exemplo, se a mudança resulta em informações mais relevantes. ( ) A verificação é melhorada utilizando-se bases de mensuração que resultam em avaliações que podem ser independentemente corroboradas diretamente, por exemplo, observando os preços, ou indiretamente, por exemplo, verificando dados de entrada de modelo. As afirmativas são, respectivamente,',null,'{"original": ["/cfc-2025-2/q13-1.png"]}','["V – V – V.", "V – V – F.", "V – F – V.", "F – V – V."]'::jsonb,'D',null from public.exams where slug='cfc-2025-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,14,'Ciências Contábeis','A NBC TG 28 (R4) - PROPRIEDADES PARA INVESTIMENTO trata de definição, classificação e mensuração de propriedades para investimento. Sobre esse item, analise as seguintes afirmativas: I. Propriedade para Investimento é classificada dentro do subgrupo investimento no ativo circulante. II. Propriedade para investimento é um terreno, edifício ou veículo mantido pela entidade para auferir aluguel ou valorização do capital. III. Propriedade para investimento no momento da aquisição deve ser mensurada pelo seu custo. Está correto o que se afirma em',null,'{"original": ["/cfc-2025-2/q14-1.png"]}','["II e III, apenas.", "III, apenas.", "I, II e III.", "II, apenas."]'::jsonb,'B',null from public.exams where slug='cfc-2025-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,15,'Ciências Contábeis','Um ativo individual ou um grupo de ativos mantido para venda são ativos a ser alienados, por venda ou de outra forma, em conjunto como um grupo de ativos em uma só transação, e passivos diretamente associados a esses ativos que serão transferidos na transação. De acordo com a NBC TG 31 (R4) - ATIVO NÃO CIRCULANTE MANTIDO PARA VENDA E OPERAÇÃO DESCONTINUADA, a depreciação do ativo ou grupo de ativos mantidos para venda deve',null,'{"original": ["/cfc-2025-2/q15-1.png"]}','["ser parcial, pois o ativo ou grupo de ativos ainda está operando.", "ser mantida até a venda ser concretizada.", "ser interrompida quando o ativo ou grupo de ativos for reclassificado como mantido para venda.", "continuar como estava antes da reclassificação."]'::jsonb,'C',null from public.exams where slug='cfc-2025-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,16,'Ciências Contábeis','De acordo com a NBC TG 01 (R4) - REDUÇÃO AO VALOR RECUPERÁVEL DE ATIVOS, o valor em uso é o valor presente de fluxos de caixa futuros esperados que devem advir de um ativo ou de unidade geradora de caixa. Avalie se os seguintes elementos devem ser refletidos no cálculo do valor em uso do ativo: I. O valor pago na aquisição do ativo. II. As expectativas acerca de possíveis variações no montante ou no período de ocorrência desses fluxos de caixa futuros. III. As estimativas dos fluxos de caixa futuros que a entidade espera obter com esse ativo. IV. O valor do dinheiro no tempo, representado pela atual taxa de juros livre de risco. Estão corretos os elementos',null,'{"original": ["/cfc-2025-2/q16-1.png"]}','["I, II e III, apenas.", "I e II, apenas.", "III e IV, apenas.", "II, III e IV, apenas."]'::jsonb,'D',null from public.exams where slug='cfc-2025-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,17,'Ciências Contábeis','O ágio por expectativa de rentabilidade futura (goodwill) reconhecido em uma combinação de negócios é um ativo que representa benefícios econômicos futuros advindos de outros ativos adquiridos na combinação de negócios que não são identificados individualmente e não são reconhecidos separadamente. De acordo com a NBC TG 04 (R4) - ATIVO INTANGÍVEL e com a NBC TG 15 (R4) - COMBINAÇÃO DE NEGÓCIOS, a empresa adquirente deve reconhecer, na data da aquisição, separadamente do ágio derivado da expectativa de rentabilidade futura (goodwill) apurado em uma combinação de negócios, um ativo intangível da adquirida, independentemente de o ativo ter sido reconhecido pela adquirida antes da aquisição da empresa. A perda por desvalorização reconhecida para o ágio por expectativa de rentabilidade futura (goodwill) não deve ser revertida em período subsequente, pois',null,'{"original": ["/cfc-2025-2/q17-1.png"]}','["não pode ser amortizada.", "no plano de contas não há rubrica apropriada.", "gera fluxos de caixa, independentemente de outros ativos ou grupos de ativos.", "é equivalente ao goodwill gerado internamente."]'::jsonb,'D',null from public.exams where slug='cfc-2025-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,18,'Ciências Contábeis','A Demonstração do Valor Adicionado (DVA) busca evidenciar o valor e a distribuição da riqueza econômica gerada pelas atividades da sociedade empresária, incluindo também o valor adicionado recebido em transferência. A riqueza gerada é evidenciada na distribuição entre o capital (Remuneração de capital próprio e de terceiros), trabalho (Pessoal) e governo (Impostos, taxas e contribuições). Relacione cada item a seguir ao respectivo componente da distribuição da riqueza, conforme disposto na NBC TG 09 (R1) - DEMONSTRAÇÃO DO VALOR ADICIONADO. ( ) Fundo de Garantia por Tempo de Serviços (FGTS) ( ) Aluguéis pagos ( ) Dividendos distribuídos ( ) Contribuição Social sobre o Lucro Líquido (CSLL) 1. Pessoal 2. Impostos, taxas e contribuições 3. Remuneração de capital de terceiros 4. Remuneração de capital próprio A relação correta, na ordem apresentada, é',null,'{"original": ["/cfc-2025-2/q18-1.png"]}','["1 – 2 – 3 – 4.", "2 – 3 – 4 – 1.", "2 – 4 – 3 – 1.", "1 – 3 – 4 – 2."]'::jsonb,'D',null from public.exams where slug='cfc-2025-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,19,'Ciências Contábeis','A empresa Delta S.A. adquiriu uma máquina por R$ 350.000,00 em 01/01/2020. No momento da aquisição, a administração de Delta S.A. estimou a vida útil desse ativo em 10 anos e um valor residual de R$ 50.000,00. A máquina estava disponível para uso em 01/01/2020 e a empresa adotou o método de depreciação linear. Em 31/12/2023, a empresa procedeu a uma revisão das suas estimativas, conforme previsto no NBC TG 27 (R4) - ATIVO IMOBILIZADO, e constatou as seguintes informações: • Vida útil remanescente: 9 anos; • Valor Residual: R$ 50.000,00. Com base exclusivamente nas informações apresentadas, o valor da depreciação anual dessa máquina a partir de 01/01/2024 será de',null,'{"original": ["/cfc-2025-2/q19-1.png"]}','["R$ 35.000,00.", "R$ 30.000,00.", "R$ 20.000,00.", "R$ 15.000,00."]'::jsonb,'C',null from public.exams where slug='cfc-2025-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,20,'Ciências Contábeis','A NBC TG ESTRUTURA CONCEITUAL estabelece os conceitos dos elementos das demonstrações contábeis. Com base nessa norma, avalie as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) Ativo é um recurso econômico presente de propriedade da entidade como resultado de eventos passados. ( ) Passivo é uma obrigação futura da entidade de transferir um recurso econômico como resultado de eventos passados. ( ) Receitas são aumentos nos ativos, ou reduções nos passivos, que resultam em aumento no patrimônio líquido, exceto aqueles referentes a contribuições de detentores de direitos sobre o patrimônio. ( ) Despesas são reduções nos ativos, ou aumentos nos passivos, que resultam em reduções no patrimônio líquido, exceto aqueles referentes a distribuições aos detentores de direitos sobre o patrimônio. As afirmativas são, respectivamente,',null,'{"original": ["/cfc-2025-2/q20-1.png"]}','["F – F – V – V.", "F – V – F – V.", "V – F – V – F.", "V – V – F – F."]'::jsonb,'A',null from public.exams where slug='cfc-2025-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,21,'Ciências Contábeis','A empresa Alfa S.A. adquiriu, por R$ 1.300.000,00, no dia 01/01/2025, 80% do capital da empresa Beta S.A., adquirindo nessa data o seu controle. Na data da aquisição: 1. o valor contábil do patrimônio líquido da empresa Beta S.A. era de R$ 1.000.000,00; 2. o valor líquido dos ativos identificáveis e dos passivos da empresa Beta S.A. correspondentes a 100% de seu capital social, mensurados a valor justo, era de R$ 1.500.000,00. Com base exclusivamente nos dados apresentados e na NBC TG 15 (R4) – COMBINAÇÃO DE NEGÓCIOS, avalie as afirmativas abaixo, com relação à contabilização ocorrida na empresa Alfa S.A.: I. Foi registrado um goodwill no valor de R$ 100.000,00. II. Foi registrada uma compra vantajosa no valor de R$ 200.000,00. III. Foi registrado um ágio ou mais-valia dos ativos no valor de R$ 400.000,00. IV. Foi registrado um ágio ou mais-valia dos ativos no valor de R$ 500.000,00. Estão corretas as afirmativas',null,'{"original": ["/cfc-2025-2/q21-1.png"]}','["I e III, apenas.", "I e IV, apenas.", "II e III, apenas.", "II e IV, apenas."]'::jsonb,'A',null from public.exams where slug='cfc-2025-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,22,'Ciências Contábeis','Influência significativa é o poder de participar das decisões sobre políticas financeiras e operacionais de uma investida, mas sem que haja o controle individual ou o conjunto dessas políticas. A NBC TG 18 (R4) - INVESTIMENTO EM COLIGADA determina que a existência de influência significativa por investidor geralmente é evidenciada por uma ou mais das seguintes formas, à exceção de uma. Assinale-a.',null,'{"original": ["/cfc-2025-2/q22-1.png"]}','["Indicação de funcionários para a investida.", "Operações materiais entre o investidor e a investida.", "Intercâmbio de diretores ou gerentes.", "Fornecimento de informação técnica essencial."]'::jsonb,'A',null from public.exams where slug='cfc-2025-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,23,'Ciências Contábeis','A empresa ABCDE possui os seguintes registros referentes às movimentações em determinado período: • Compras: ................................................................................................................................................................. R$ 5.000,00. • Estoque inicial: ........................................................................................................................................................ R$ 3.000,00. • Estoque final: .......................................................................................................................................................... R$ 2.000,00. • Vendas: ................................................................................................................................................................. R$ 30.000,00. • Despesas gerais: ..................................................................................................................................................... R$ 1.000,00. • Devolução de compras: ............................................................................................................................................. R$ 500,00. Com base nesses registros, é possível afirmar que a empresa obteve o Custo das Mercadorias Vendidas (CMV) de',null,'{"original": ["/cfc-2025-2/q23-1.png"]}','["R$ 6.000,00.", "R$ 7.500,00.", "R$ 8.000,00.", "R$ 5.500,00."]'::jsonb,'D',null from public.exams where slug='cfc-2025-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,24,'Ciências Contábeis','A empresa S.A. possuía, em 31/12/2024, obrigações presentes como resultados de eventos passados cuja saída de recursos envolvendo benefícios futuros na liquidação esteve sujeita à análise, com a classificação disposta na tabela a seguir: Probabilidade de ocorrência de Tipo de Obrigação Valor da mensuração por estimativa confiável saída de recurso Garantia de venda R$ 5.000,00 Provável Terreno contaminado e obrigação não formalizada R$ 15.000,00 Provável Processo Trabalhista I R$ 10.000,00 Remota Processo Trabalhista II R$ 20.000,00 Possível Há impossibilidade de estimar confiavelmente no Processo Fiscal Possível momento. Com base nos dados, seguindo a NBC TG 25 (R2) - PROVISÕES, PASSIVOS CONTINGENTES E ATIVOS CONTINGENTES, o montante a ser reconhecido como provisões no Balanço Patrimonial da empresa deve ser de',null,'{"original": ["/cfc-2025-2/q24-1.png"]}','["R$ 20.000,00.", "R$ 40.000,00.", "R$ 30.000,00.", "R$ 50.000,00."]'::jsonb,'A',null from public.exams where slug='cfc-2025-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,25,'Ciências Contábeis','A empresa Serviços S.A. encerrou seu exercício em 31/12/2024, deixando de efetuar o lançamento referente à receita de serviços prestados a um cliente em dezembro e ainda não recebidos, deixando de obedecer, assim, ao regime de competência. Como consequência do erro cometido pela ausência desse registro,',null,'{"original": ["/cfc-2025-2/q25-1.png"]}','["o saldo da conta clientes ficou superavaliado.", "o saldo do disponível ficou subavaliado.", "a receita do exercício ficou superavaliada.", "o lucro do exercício ficou subavaliado."]'::jsonb,'D',null from public.exams where slug='cfc-2025-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,26,'Ciências Contábeis','A Cia. Gold vende pulseiras. Em 31/12/2024, não havia estoque inicial de pulseiras. No primeiro trimestre de 2025 aconteceram os seguintes fatos: • 05/01: compra de 20 pulseiras por R$ 10.000,00; • 25/01: venda de 10 pulseiras por R$ 1.200,00 cada; • 05/02: compra de 12 pulseiras por R$ 7.200,00; • 20/02: venda de 11 pulseiras por R$ 1.200,00 cada; • 10/03: compra de 8 pulseiras por R$ 5.200,00; • 27/03: venda de 5 pulseiras por R$ 1.400,00 cada. Assinale a opção que indica o valor aproximado do estoque final de pulseiras da Cia. Gold em 31/03/2025, considerando que a empresa utiliza o método do Custo Médio Ponderado Móvel em base diária.',null,'{"original": ["/cfc-2025-2/q26-1.png"]}','["R$ 7.840,00.", "R$ 8.326,00.", "R$ 9.100,00.", "R$ 10.905,00."]'::jsonb,'B',null from public.exams where slug='cfc-2025-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,27,'Ciências Contábeis','Uma loja de cosméticos começou a funcionar em 01/07/2024. No segundo semestre de 2024, aconteceram os seguintes fatos: • Integralização de capital social em dinheiro: R$ 300.000,00. • Compra à vista de móveis e utensílios para a loja: R$ 40.000,00. • Compra à vista de estoque para revenda: R$ 80.000,00. • Pagamento do aluguel do semestre: R$ 30.000,00. • Pagamento antecipado do aluguel do primeiro trimestre de 2025: R$ 18.000,00. • Venda de todo o estoque por R$ 400.000,00, sendo que metade do valor já foi recebido e o restante deverá ser recebido no primeiro semestre de 2025. A loja estima inadimplência de 5%. • Reconhecimento e pagamento de despesas diversas: R$ 12.000,00. • Reconhecimento da despesa de depreciação: R$ 4.000,00. O fluxo de caixa gerado pela atividade operacional em 2024, de acordo com as diretrizes da NBC TG 03 (R3) – DEMONSTRAÇÃO DOS FLUXOS DE CAIXA foi de',null,'{"original": ["/cfc-2025-2/q27-1.png"]}','["R$ 20.000,00.", "R$ 50.000,00.", "R$ 60.000,00.", "R$ 360.000,00."]'::jsonb,'C',null from public.exams where slug='cfc-2025-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,28,'Ciências Contábeis','Em 01/12/2024, uma sociedade empresária apresentava, em seu Balanço Patrimonial, como ativo imobilizado, um terreno, cujo valor contábil era de R$ 80.000,00. Em 31/12/2024, a sociedade empresária realizou um teste de recuperabilidade em seus ativos imobilizados. Foi constatado que o valor em uso do terreno era de R$ 75.000,00. Para que não haja reconhecimento de perda de recuperabilidade do terreno, o valor justo líquido de despesa de venda deve ser',null,'{"original": ["/cfc-2025-2/q28-1.png"]}','["menor do que R$ 75.000,00.", "maior do que R$ 79.999,99.", "entre R$ 72.000,00 e R$ 74.999,99.", "entre R$ 75.000,00 e R$ 79.999,99."]'::jsonb,'B',null from public.exams where slug='cfc-2025-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,29,'Ciências Contábeis','Em junho de 2025, uma companhia aérea reconheceu as seguintes receitas: • com a marcação de assentos: R$ 150.000,00; • com equivalência patrimonial: R$ 200.000,00; • com a venda de passagens: R$ 900.000,00. Nesse mês, a companhia aérea reconheceu como Receita, na primeira linha da Demonstração do Resultado do Exercício, o seguinte montante:',null,'{"original": ["/cfc-2025-2/q29-1.png"]}','["R$ 900.000,00.", "R$ 1.050.000,00.", "R$ 1.100.000,00.", "R$ 1.250.000,00."]'::jsonb,'B',null from public.exams where slug='cfc-2025-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,30,'Ciências Contábeis','Em 01/01/2025, uma livraria tinha em estoque 20 livros “Estatística Simples”. Cada livro tinha sido adquirido por R$ 80,00 e era vendido por R$ 140,00. No primeiro trimestre desse ano, a movimentação do livro foi a seguinte: • 28/01: venda de 10 livros por R$ 140,00. • 05/02: compra de 15 livros por R$ 90,00. • 25/02: venda de 18 livros por R$ 150,00. • 05/03: compra de 20 livros por R$ 95,00. • 28/03: venda de 25 livros por R$ 150,00. O custo das mercadorias vendidas no primeiro trimestre de 2025, considerando que a livraria utiliza o método PEPS para avaliação de estoque, foi de',null,'{"original": ["/cfc-2025-2/q30-1.png"]}','["R$ 3.860,00.", "R$ 4.220,00.", "R$ 4.660,00.", "R$ 5.035,00."]'::jsonb,'C',null from public.exams where slug='cfc-2025-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,31,'Ciências Contábeis','A compreensão dos conceitos e métodos relacionados à Demonstração do Resultado do Exercício (DRE) e à Demonstração do Resultado Abrangente (DRA) é fundamental para a adequada análise das variações do patrimônio líquido e para a tomada de decisões baseadas nos resultados operacionais. A respeito do tema, analise as seguintes afirmativas: I. A recompra de ações de emissão da própria entidade para manutenção em tesouraria afeta o resultado abrangente por representar uma redução no patrimônio líquido. II. O resultado abrangente compreende todos os componentes da demonstração do resultado e dos outros resultados abrangentes. III. Pelo método da natureza da despesa, as despesas são classificadas conforme sua função, como administrativas, comerciais e de produção, facilitando a análise do custo dos produtos vendidos. IV. A informação sobre a natureza das despesas é útil para prever os fluxos de caixa futuros e requer divulgação adicional quando a classificação adotada na DRE for baseada no método da função das despesas. V. A entidade deve apresentar rubricas ou itens de receitas ou despesas como itens extraordinários, quer na demonstração do resultado abrangente, quer na demonstração do resultado do período, quer nas notas explicativas. De acordo com a NBC TG 26 (R5) - APRESENTAÇÃO DAS DEMONSTRAÇÕES CONTÁBEIS, estão corretas as afirmativas',null,'{"original": ["/cfc-2025-2/q31-1.png"]}','["II e IV, apenas.", "I, III e V, apenas.", "II, III e IV, apenas.", "I, II, IV e V, apenas."]'::jsonb,'A',null from public.exams where slug='cfc-2025-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,32,'Ciências Contábeis','A empresa S.A. é especializada na construção de galpões industriais sob encomenda de acordo com especificações exclusivas de cada cliente. Os contratos firmados pela empresa preveem que a construção ocorra no terreno do cliente, com pagamentos mensais vinculados ao andamento da obra, que pode durar de 6 a 10 meses. Considerando as informações apresentadas e os preceitos da NBC TG 47 – RECEITA DE CONTRATO COM CLIENTE, o reconhecimento da receita deve ocorrer',null,'{"original": ["/cfc-2025-2/q32-1.png"]}','["somente após a emissão do certificado de aceitação técnica da obra pelo cliente.", "no momento da conclusão da obra, quando todos os riscos e benefícios são transferidos.", "no início do contrato, pois o pagamento mensal caracteriza o reconhecimento da receita.", "ao longo do tempo, pois o desempenho da entidade cria ou melhora ativo que o cliente controla à medida que é construído."]'::jsonb,'D',null from public.exams where slug='cfc-2025-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,33,'Ciências Contábeis','Uma empresa S.A. celebrou um contrato no valor de R$ 30.000,00 para utilizar um equipamento por um período de 10 meses, cujo ativo subjacente do contrato foi considerado de baixo valor pela empresa. A administração da empresa S.A. decidiu aplicar a isenção de reconhecimento autorizada pelo item 5 da NBC TG 06 (R3). Considerando-se as informações apresentadas e os preceitos da NBC TG 06 (R3) – ARRENDAMENTOS, o tratamento contábil para esse contrato é',null,'{"original": ["/cfc-2025-2/q33-1.png"]}','["registrar o valor total do contrato antecipadamente como despesa no início do contrato.", "capitalizar o valor do contrato como ativo imobilizado, amortizando ao longo do contrato.", "reconhecer os pagamentos do arrendamento como despesa no resultado, de forma linear ou sistemática, ao longo do prazo do contrato.", "reconhecer um ativo de direito de uso e um passivo de arrendamento, ambos, ao valor presente estipulado no contrato."]'::jsonb,'C',null from public.exams where slug='cfc-2025-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,34,'Ciências Contábeis','Uma empresa que atua na produção de medicamentos há 10 anos decidiu trocar dois de seus equipamentos (classificados como ativo imobilizado) mais relevantes por outros com tecnologia mais atualizada com o objetivo de redução nos seus custos de produção. As informações sobre os equipamentos retirados de operação são relatadas a seguir: Valor Contábil Líquido = R$ 500.000,00 Equipamento 1 Valor Justo Líquido = R$ 750.000,00 Valor Contábil Líquido = R$ 1.500.000,00 Equipamento 2 Valor Justo Líquido = R$ 1.250.000,00 Sabendo que os novos equipamentos adquiridos já estão em uso, um plano de venda desses ativos (Equipamentos 1 e 2) foi submetido e aprovado pelo Conselho de Administração, que considerou a venda altamente provável de ser concluída nos próximos 12 meses. Logo, segundo a NBC TG 31 (R3) – ATIVO NÃO CIRCULANTE MANTIDO PARA VENDA E OPERAÇÃO DESCONTINUADA, a mensuração subsequente dos equipamentos a ser adotada pela empresa a partir da decisão do Conselho de Administração é:',null,'{"original": ["/cfc-2025-2/q34-1.png"]}','["Equipamento 1 por R$ 500.000,00 e Equipamento 2 por R$ 1.250.000,00.", "Equipamento 1 por R$ 500.000,00 e Equipamento 2 por R$ 1.500.000,00.", "Equipamento 1 por R$ 750.000,00 e Equipamento 2 por R$ 1.500.000,00.", "Equipamento 1 por R$ 750.000,00 e Equipamento 2 por R$ 1.250.000,00."]'::jsonb,'A',null from public.exams where slug='cfc-2025-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,35,'Ciências Contábeis','A Contabilidade de Custos possui uma linguagem própria que permite ao profissional da contabilidade constituir o processo de análise, apuração e divulgação das informações relacionadas a custos, à medida que se mostrarem pertinentes de acordo com a necessidade informacional dos inúmeros stakeholders. Tomando por base esse processo de terminologias na contabilidade de custos, assinale a afirmativa correta.',null,'{"original": ["/cfc-2025-2/q35-1.png"]}','["Os gastos representam a compra de um produto ou serviço que tem por capacidade gerar o dispêndio de recursos financeiros por parte da empresa, a exemplo da aquisição de um imobilizado.", "Os custos representam um sacrifício monetário referente ao pagamento dos gastos, a exemplo do consumo de matéria-prima.", "As despesas podem ser entendidas como os recursos utilizados na constituição de bens ou serviços em uma indústria, como exemplo tem-se as despesas com vendas e comissões.", "As perdas são gastos anormais e involuntários do processo produtivo e já estão incluídas no custo do produto."]'::jsonb,'A',null from public.exams where slug='cfc-2025-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,36,'Ciências Contábeis','Uma empresa realizou a contagem de seus estoques, acabando por superavaliar o estoque inicial, mantendo o controle de compras e estoque final nos valores corretos. Em consequência da superavaliação do estoque inicial é correto afirmar que',null,'{"original": ["/cfc-2025-2/q36-1.png"]}','["a receita de vendas do período corrente foi subavaliada.", "o lucro acumulado do período corrente foi superavaliado.", "o custo dos produtos vendidos do período corrente foi superavaliado.", "o estoque final foi subavaliado."]'::jsonb,'C',null from public.exams where slug='cfc-2025-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,37,'Ciências Contábeis','A Fazenda Laticínios Campo Verde Ltda. produz e comercializa queijos artesanais tipo minas frescal. No mês de julho de 2025, quando a empresa não possuía estoque inicial, foram produzidas 12.000 unidades de queijo. Nesse mesmo mês, vendeu 9.000 unidades a um preço unitário de R$ 25,00. Os custos variáveis totais somaram R$ 135.000,00 e os custos fixos totalizaram R$ 42.000,00. As despesas fixas totalizaram R$ 25.000,00, e as despesas variáveis com comissão aos vendedores corresponderam a 5% do valor de cada unidade vendida. Considerando os dados fornecidos e desconsiderando efeitos tributários, os lucros líquidos com as vendas em julho de 2025, utilizando, respectivamente, os métodos de custeio por absorção e custeio variável, foram de',null,'{"original": ["/cfc-2025-2/q37-1.png"]}','["R$ 45.470,00 e R$ 11.750,00.", "R$ 56.000,00 e R$ 56.000,00.", "R$ 45.470,00 e R$ 112.500,00.", "R$ 56.000,00 e R$ 45.500,00."]'::jsonb,'D',null from public.exams where slug='cfc-2025-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,38,'Ciências Contábeis','A Indústria Paranaguá Ltda. utiliza o sistema de custeio baseado em atividades (ABC). No mês de junho de 2025, foram apuradas as seguintes informações para os produtos X, Y e Z: Mão de Obra Direta Produto Material Direto (R$) Pedidos de Mudança Quilowatts-hora (kWh) (R$) X 35.000,00 18.000,00 28 12.000 Y 40.000,00 12.000,00 20 14.000 Z 25.000,00 10.000,00 32 14.000 Total 100.000,00 40.000,00 80 40.000 Os custos indiretos de manufatura totalizaram R$ 200.000,00, distribuídos entre as seguintes atividades: • Gerenciamento de mudanças de projeto (baseado em pedidos): R$ 140.000,00; • Geração e uso de energia operacional (baseado em kWh): R$ 60.000,00. No período, foram produzidas 1.200 unidades do produto X, 1.500 unidades do produto Y e 2.000 unidades do produto Z. Com base nesses dados, os custos unitários dos produtos X, Y e Z, respectivamente, são',null,'{"original": ["/cfc-2025-2/q38-1.png"]}','["R$ 98,50; R$ 70,00; R$ 60,00.", "R$ 90,00; R$ 80,00; R$ 65,00.", "R$ 105,00; R$ 74,00; R$ 52,00.", "R$ 100,00; R$ 72,00; R$ 56,00."]'::jsonb,'D',null from public.exams where slug='cfc-2025-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,39,'Ciências Contábeis','Em 31/12/2023, uma sociedade empresária apresentava os seguintes saldos em seus ativos e passivos: • Ativo Circulante: R$ 50.000,00; • Ativo Realizável a Longo Prazo: R$ 30.000,00; • Ativo Imobilizado: R$ 120.000,00; • Passivo Circulante: R$ 40.000,00; • Passivo não Circulante: R$ 100.000,00. A proporção de capital próprio que financia o ativo da sociedade empresária foi igual a',null,'{"original": ["/cfc-2025-2/q39-1.png"]}','["30%.", "40%.", "60%.", "70%."]'::jsonb,'A',null from public.exams where slug='cfc-2025-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,40,'Ciências Contábeis','Uma fábrica produz e vende apenas malas de mão. O custo fixo mensal da fábrica é de R$ 10.000,00. As malas são produzidas em dois modelos: com duas rodinhas e com quatro rodinhas. As malas com duas rodinhas são vendidas por R$ 200,00 cada, enquanto as malas com quatro rodinhas são vendidas por R$ 370,00 cada. Além disso, o custo variável da mala com duas rodinhas é de R$ 80,00, e o custo variável da de quatro rodinhas é de R$ 140,00. No primeiro trimestre de 2025, a fábrica tinha em estoque 500 unidades de rodinhas e não era possível adquirir mais. No período, as demandas pela produção de malas com duas e quatro rodinhas eram, respectivamente, de 80 e de 100. Considerando que a fábrica tinha como objetivo maximizar o seu lucro, assinale a opção que indica a produção de malas de duas e quatro rodinhas, respectivamente, no período.',null,'{"original": ["/cfc-2025-2/q40-1.png"]}','["50 e 85.", "50 e 100.", "80 e 85.", "80 e 100."]'::jsonb,'C',null from public.exams where slug='cfc-2025-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,41,'Ciências Contábeis','A empresa Gigulefere S.A. adota o custo padrão e verificou, em abril de 2025, alguns dados para analisar a variação ocorrida (realizado x orçado). Abaixo estão apresentados os dados apurados pelo contador: • a mão de obra direta efetivamente consumida foi 50 horas superior ao padrão estabelecido de 1.500 horas. • o custo incorrido com a mão de obra direta, por unidade de tempo, ficou R$ 7,00 abaixo do valor previsto de R$ 150,00 por hora. Com base exclusivamente nos dados apresentados pelo contador, as variações de taxa e eficiência, respectivamente, ocorridas no mês de abril de 2025, foram',null,'{"original": ["/cfc-2025-2/q41-1.png"]}','["350 desfavorável e 225.000 favorável.", "10.500 favorável e 7.500 desfavorável.", "75.000 desfavorável e 225.000 favorável.", "1.050 favorável e 75.000 desfavorável."]'::jsonb,'B',null from public.exams where slug='cfc-2025-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,42,'Ciências Contábeis','Em janeiro de 2024, um município adquiriu computadores para o edifício-sede da Prefeitura por R$ 50.000,00, classificandoos como ativo imobilizado. O transporte do estabelecimento do fornecedor para o edifício foi de R$ 5.000,00, pagos pelo município. Além disso, os custos de preparação dos locais para a instalação dos computadores foram de R$ 10.000,00. Após estarem devidamente instalados, o município gastou R$ 8.000,00 para treinar os funcionários que utilizarão esses computadores. O valor a ser reconhecido a título desse ativo, inicialmente, é',null,'{"original": ["/cfc-2025-2/q42-1.png"]}','["R$ 55.000,00.", "R$ 63.000,00.", "R$ 65.000,00.", "R$ 73.000,00."]'::jsonb,'C',null from public.exams where slug='cfc-2025-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,43,'Ciências Contábeis','Uma escola do setor público serve, diariamente, café da manhã e almoço a seus alunos. Para as refeições, a escola adquire, semanalmente, frutas e verduras, e trimestralmente, alimentos não perecíveis. Todas as compras são pagas à vista. Em julho, a escola gastou R$ 4.000,00 com frutas e verduras e R$ 20.000,00 com os produtos não perecíveis, para serem estocados e utilizados até setembro. Os caixas consumidos, respectivamente, pela Atividade Operacional e pela Atividade de Investimento, na Demonstração dos Fluxos de Caixa da escola, foram',null,'{"original": ["/cfc-2025-2/q43-1.png"]}','["zero e R$ 24.000,00.", "R$ 4.000,00 e R$ 20.000,00.", "R$ 20.000,00 e R$ 4.000,00.", "R$ 24.000,00 e zero."]'::jsonb,'D',null from public.exams where slug='cfc-2025-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,44,'Ciências Contábeis','De acordo com a NBC TSP - RECEITA DE TRANSAÇÃO SEM CONTRAPRESTAÇÃO, quando uma entidade do setor público adquire um ativo por meio de uma transação sem contraprestação, esse ativo deve ser mensurado inicialmente',null,'{"original": ["/cfc-2025-2/q44-1.png"]}','["pelo valor de ativo similar adquirido nos último três anos pela entidade pública.", "pelo valor simbólico de R$ 1,00.", "pelo valor justo do ativo na data de aquisição.", "por valor nenhum, considerando que não houve pagamento na transação."]'::jsonb,'C',null from public.exams where slug='cfc-2025-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,45,'Ciências Contábeis','No planejamento orçamentário, a projeção da receita líquida de vendas é fundamental para estimar os resultados financeiros do período. Para isso, devem ser consideradas as quantidades a serem vendidas, o preço unitário e eventuais descontos concedidos. Uma empresa projeta vender 4.000 unidades de seu produto no próximo trimestre. O preço de venda unitário é de R$ 120,00, e a empresa oferece um desconto comercial de 5% sobre o valor total. Considerando essas premissas, o valor estimado da receita líquida de vendas no orçamento trimestral será de',null,'{"original": ["/cfc-2025-2/q45-1.png"]}','["R$ 456.000,00.", "R$ 480.000,00.", "R$ 484.000,00.", "R$ 504.000,00."]'::jsonb,'A',null from public.exams where slug='cfc-2025-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,46,'Ciências Contábeis','Durante a reestruturação de uma empresa, o contador passou a atuar estrategicamente na controladoria e no compliance, contribuindo para o aprimoramento da gestão, monitorando indicadores e apoiando decisões. Ele também assegurou a conformidade com normas legais e regulatórias. Com isso, fortaleceu seu papel na governança e na transparência organizacional. Considerando essa atuação conjunta, uma atribuição que caracteriza adequadamente essa integração funcional é',null,'{"original": ["/cfc-2025-2/q46-1.png"]}','["a mitigação de riscos.", "o acompanhamento de metas.", "o monitoramento da integridade dos controles internos.", "o apoio à gestão com foco em desempenho e conformidade."]'::jsonb,'D',null from public.exams where slug='cfc-2025-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,47,'Ciências Contábeis','Um Auditor foi contratado por uma determinada empresa S.A. para realizar auditoria independente e, na ocasião, deparou com a seguinte situação: nos demonstrativos auxiliares, verificou-se que a empresa adota o método linear de depreciação das máquinas e registra o lançamento mensalmente na contabilidade. Conforme a NBC TA 500 (R1) - EVIDÊNCIA DE AUDITORIA, o procedimento que deverá ser adotado para a confirmação da exatidão dos valores lançados é',null,'{"original": ["/cfc-2025-2/q47-1.png"]}','["a confirmação externa.", "a inspeção.", "o recálculo.", "a indagação."]'::jsonb,'C',null from public.exams where slug='cfc-2025-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,48,'Ciências Contábeis','De acordo com a NBC TA 300 (R1) – PLANEJAMENTO DA AUDITORIA DE DEMONSTRAÇÕES CONTÁBEIS, o envolvimento do sócio do trabalho e de outros membros-chave da equipe de trabalho no planejamento da auditoria',null,'{"original": ["/cfc-2025-2/q48-1.png"]}','["garante o controle e o cumprimento das etapas necessárias, fornecendo agilidade ao processo de planejamento.", "incorpora a sua experiência e seus pontos de vista, otimizando a eficácia e a eficiência do processo de planejamento.", "aumenta a admiração e o respeito transferidos pela equipe, proporcionando sinergia para o processo de planejamento.", "melhora a proximidade e o relacionamento com a equipe, contribuindo para a qualidade do processo de planejamento."]'::jsonb,'B',null from public.exams where slug='cfc-2025-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,49,'Ciências Contábeis','Considerando as disposições da NBC TP 01 (R1) - PERÍCIA CONTÁBIL, avalie as assertivas a seguir. I. A perícia contábil é o conjunto de procedimentos técnico-científicos destinados a levar à instância decisória elementos de prova necessários a subsidiar a justa solução do litígio ou constatação de fato, mediante laudo pericial contábil e/ou parecer pericial contábil, em conformidade com as normas jurídicas e profissionais e com a legislação específica no que for pertinente. II. O laudo pericial contábil e o parecer pericial contábil não têm por limite o objeto da perícia deferida ou contratada. III. A perícia contábil é de competência do contador em situação regular em Conselho Regional de Contabilidade ou de profissional equivalente, desde que seja detentor de notório conhecimento sobre a matéria. IV. O planejamento da perícia é a etapa do trabalho pericial na qual o perito estabelece as diretrizes e a metodologia a serem aplicadas. Estão corretas apenas as assertivas',null,'{"original": ["/cfc-2025-2/q49-1.png"]}','["I e II.", "I e III.", "II e III.", "I e IV."]'::jsonb,'A/B/C/D/E',null from public.exams where slug='cfc-2025-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,50,'Ciências Contábeis','O Parecer Pericial Contábil é um documento elaborado pelo perito-contador assistente, destinado a analisar, comentar ou contestar o Laudo Pericial Contábil elaborado pelo perito-contador nomeado pelo juízo. O parecer deve ser redigido de forma clara, objetiva e técnica, seguindo rigorosamente as normas contábeis. Segundo a NBC TP 01 - PERÍCIA CONTÁBIL, uma condição para a emissão do Parecer Pericial Contábil é que o Parecer Pericial Contábil deve',null,'{"original": ["/cfc-2025-2/q50-1.png"]}','["ser emitido, independentemente de concordância ou discordância com o Laudo Pericial Contábil.", "ser emitido apenas quando houver concordância total com o Laudo Pericial Contábil.", "ser emitido somente se houver divergência parcial ou total em relação ao Laudo Pericial Contábil.", "ser emitido contendo uma análise sobre a conduta do perito-contador responsável pelo Laudo Pericial Contábil."]'::jsonb,'A/B/C/D/E',null from public.exams where slug='cfc-2025-2' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.exams(slug,title,source,year) values ('cfc-2025-1','CFC 2025.1 — Exame de Suficiência — Contador — Tipo 1','cfc','2025') on conflict(slug) do update set title=excluded.title,source=excluded.source,year=excluded.year;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,1,'Língua Portuguesa','Um cartaz, na porta de um supermercado, dizia: “Compre hoje! Amanhã pode estar mais caro!” Esse cartaz',null,'{"original": ["/cfc-2025-1/q1-1.png"]}','["aconselha o cliente a economizar.", "dá ordem ao cliente para ganhar tempo.", "chama a atenção do cliente para a possível falta de produtos.", "pretende ensinar o cliente a controlar seu orçamento."]'::jsonb,'A',null from public.exams where slug='cfc-2025-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,2,'Língua Portuguesa','Um famoso escritor falou sobre a leitura: “A leitura é para a mente o que a ginástica é para o corpo.” Com essa frase, o autor quer dizer que',null,'{"original": ["/cfc-2025-1/q2-1.png"]}','["exercícios físicos devem ser feitos todos os dias.", "a leitura, como a ginástica, deve ser feita diariamente.", "a leitura enriquece o nosso conhecimento.", "exercícios físicos e leitura fortalecem o corpo. MATEMÁTICA FINANCEIRA E ESTATÍSTICA"]'::jsonb,'A/B/C/D/E',null from public.exams where slug='cfc-2025-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,3,'Matemática Financeira e Estatística','Uma caixa contém seis bolas brancas e quatro bolas azuis, todas de mesmo tamanho. Se sortearmos ao acaso 3 dessas bolas, sem reposição, a probabilidade de que todas sejam brancas é igual a',null,'{"original": ["/cfc-2025-1/q3-1.png"]}','["1/3.", "1/4.", "1/5.", "1/6."]'::jsonb,'D',null from public.exams where slug='cfc-2025-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,4,'Matemática Financeira e Estatística','Em 2023, uma universidade tradicional que, até então, só ofertava cursos presenciais de graduação, resolveu se arriscar em um novo projeto. Tratava-se da abertura de seu primeiro curso 100% à distância a ser disponibilizado ao mercado. Para tal, ainda em 2023, foram investidos R$ 100.000,00 para a estruturação do referido curso. Além disso, foram estimadas despesas e receitas anuais conforme dados apresentados na sequência: Ano Receitas Despesas 2024 R$ 50.000,00 R$ 35.000,00 2025 R$ 65.000,00 R$ 30.000,00 2026 R$ 80.000,00 R$ 30.000,00 2027 R$ 90.000,00 R$ 20.000,00 2028 R$ 90.000,00 R$ 20.000,00 Considerando as informações apresentadas, é possível determinar que o payback simples ocorreu em',null,'{"original": ["/cfc-2025-1/q4-1.png", "/cfc-2025-1/q4-2.png"]}','["2025.", "2026.", "2027.", "2028. NOÇÕES DE DIREITO E LEGISLAÇÃO APLICADA"]'::jsonb,'B',null from public.exams where slug='cfc-2025-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,5,'Ciências Contábeis','Avalie se os princípios da Administração Pública incluem: I. a legalidade; II. a moralidade; III. a livre concorrência; IV. a publicidade. São de fato princípios da Administração Pública os itens',null,'{"original": ["/cfc-2025-1/q5-1.png"]}','["I e II, apenas.", "II, III e IV, apenas.", "I, II e IV, apenas.", "I, II, III e IV."]'::jsonb,'C',null from public.exams where slug='cfc-2025-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,6,'Ciências Contábeis','Entre as limitações ao poder de tributar, previstas na Constituição Federal de 1988, estão os princípios gerais do Direito Tributário que, além de estabelecer limites ao poder de tributar, garantem segurança jurídica e justiça fiscal. Sobre esse tema, assinale a afirmativa correta.',null,'{"original": ["/cfc-2025-1/q6-1.png"]}','["O princípio da anterioridade nonagesimal ou noventena estabelece que nenhum tributo pode ser cobrado antes de decorridos 90 dias da data da publicação da sua instituição ou majoração, exceto as contribuições sociais, que podem ser exigidas imediatamente.", "O princípio da legalidade tributária determina que nenhum tributo pode ser instituído ou majorado sem previsão em lei complementar.", "O princípio da isonomia garante tratamento igualitário a todos que se encontram em situação equivalente, sendo proibida qualquer distinção em razão de ocupação profissional ou função por eles exercida, independentemente da denominação jurídica dos rendimentos, títulos ou direitos.", "O princípio da irretroatividade veda a aplicação da lei a ato ou fato pretérito, ainda que a lei seja expressamente interpretativa."]'::jsonb,'C',null from public.exams where slug='cfc-2025-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,7,'Ciências Contábeis','A empresa Alfa Indústria Ltda. realizou, ao final do mês de julho, o levantamento de suas obrigações tributárias, verificando os seguintes tributos devidos: • ICMS (Imposto sobre Circulação de Mercadorias e Serviços): incidente sobre as operações de vendas realizadas no período. • ISS (Imposto sobre Serviços): devido pelos serviços prestados. • IRPJ (Imposto sobre a Renda das Pessoas Jurídicas): apurado sobre a renda tributável do exercício. Com base nessas informações, a contabilidade da empresa elaborou um demonstrativo das obrigações tributárias a pagar. De acordo com os conceitos de obrigação tributária e tributo, assinale a afirmativa correta.',null,'{"original": ["/cfc-2025-1/q7-1.png", "/cfc-2025-1/q7-2.png"]}','["O ISS e o ICMS são impostos de mesma competência tributária, pois ambos são devidos aos Estados.", "A obrigação tributária principal consiste no pagamento do tributo devido, enquanto a obrigação tributária acessória está relacionada a deveres instrumentais, como a emissão de notas fiscais e declarações ao Fisco.", "O IRPJ, por ser um imposto sobre a renda, é classificado como um tributo indireto, pois seu ônus pode ser repassado ao consumidor.", "O fato gerador do ICMS ocorre quando a empresa apura seus lucros ao final do exercício contábil. LEGISLAÇÃO E ÉTICA PROFISSIONAL"]'::jsonb,'B',null from public.exams where slug='cfc-2025-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,8,'Ciências Contábeis','De acordo com o CÓDIGO DE ÉTICA PROFISSIONAL DO CONTADOR em seu item 3: “Este código de ética profissional do contador se aplica também ao _____, no exercício de suas prerrogativas profissionais.” A lacuna fica corretamente preenchida por',null,'{"original": ["/cfc-2025-1/q8-1.png"]}','["empresário contábil.", "técnico em contabilidade.", "administrador de empresas.", "gestor financeiro."]'::jsonb,'B',null from public.exams where slug='cfc-2025-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,9,'Ciências Contábeis','A NBC PG 01 tem por objetivo fixar a conduta do contador, quando no exercício da sua atividade e nos assuntos relacionados à profissão e à classe. Com base na NBC PG 01 é correto afirmar que o contador pode',null,'{"original": ["/cfc-2025-1/q9-1.png"]}','["se utilizar de posição ocupada em entidades de classe para benefício próprio ou para proveito pessoal.", "fazer afirmações desproporcionais sobre os serviços que oferece, sua capacitação ou sobre a experiência que possui.", "se apropriar de trabalhos, iniciativas ou de soluções encontradas por colegas, que deles não tenha participado, apresentando-os como próprios.", "indicar, em qualquer modalidade ou veículo de comunicação, os títulos, as especializações, os serviços oferecidos, os trabalhos realizados e a relação de clientes, quando ela for autorizada por eles. TEORIA DA CONTABILIDADE"]'::jsonb,'D',null from public.exams where slug='cfc-2025-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,10,'Ciências Contábeis','Para que um passivo se qualifique para reconhecimento, é necessário haver não somente uma obrigação presente, mas também a probabilidade de saída de recursos que incorporem benefícios econômicos para liquidar essa obrigação. No caso de uma Provisão, o reconhecimento se dá quando: (a) a entidade tem uma obrigação presente (legal ou não formalizada) como resultado de evento passado; (b) seja provável uma necessária saída de recursos que incorporem benefícios econômicos para liquidar a obrigação; e (c) possa ser feita uma estimativa confiável do valor da obrigação. Se essas condições não forem satisfeitas, nenhuma provisão deve ser reconhecida. Em relação ao reconhecimento de um PASSIVO CONTINGENTE, de acordo com a NBC TG 25 (R2), é correto afirmar que',null,'{"original": ["/cfc-2025-1/q10-1.png"]}','["não é reconhecido e nem divulgado em notas explicativas.", "não é reconhecido, mas é divulgado em notas explicativas.", "é reconhecido e divulgado em notas explicativas.", "é reconhecido, mas não é divulgado em notas explicativas."]'::jsonb,'A/B/C/D/E',null from public.exams where slug='cfc-2025-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,11,'Ciências Contábeis','Um supermercado funciona na região sul do país. Em maio de 2024, devido às fortes chuvas, o supermercado perdeu todo o seu estoque. Nas demonstrações contábeis mensais, em 31/05/24, o supermercado optou por baixar todo o estoque, mesmo sem ter recebido um laudo oficial, de modo a tornar as demonstrações mais úteis aos tomadores de decisões. A informação apresenta a seguinte característica qualitativa:',null,'{"original": ["/cfc-2025-1/q11-1.png"]}','["neutralidade.", "materialidade.", "verificabilidade.", "tempestividade."]'::jsonb,'D',null from public.exams where slug='cfc-2025-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,12,'Ciências Contábeis','De acordo com a NBC TG Estrutura Conceitual- ESTRUTURA CONCEITUAL PARA RELATÓRIO FINANCEIRO, as demonstrações contábeis consolidadas fornecem informações sobre os ativos, passivos, patrimônio líquido, receitas e despesas',null,'{"original": ["/cfc-2025-1/q12-1.png"]}','["apenas das controladas.", "apenas da controladora.", "da controladora e de suas controladas, como entidades independentes.", "da controladora e de suas controladas, como uma única entidade que reporta."]'::jsonb,'D',null from public.exams where slug='cfc-2025-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,13,'Ciências Contábeis','De acordo com a NBC TG Estrutura Conceitual - ESTRUTURA CONCEITUAL PARA RELATÓRIO FINANCEIRO, patrimônio líquido é a participação nos ativos da entidade após',null,'{"original": ["/cfc-2025-1/q13-1.png"]}','["a dedução de seus passivos.", "a dedução de suas despesas.", "o acréscimo de suas receitas.", "o acréscimo de seus passivos. PRINCÍPIOS DE CONTABILIDADE E NORMAS BRASILEIRAS DE CONTABILIDADE"]'::jsonb,'A',null from public.exams where slug='cfc-2025-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,14,'Ciências Contábeis','Segundo a NBC TG ESTRUTURA CONCEITUAL, para a representação dos relatórios financeiros ser fidedigna ela precisa ser',null,'{"original": ["/cfc-2025-1/q14-1.png"]}','["completa, neutra e isenta de erros.", "confiável, tempestiva e com erros mínimos.", "tempestiva, útil e comparável.", "consistente, completa e compreensível."]'::jsonb,'A',null from public.exams where slug='cfc-2025-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,15,'Ciências Contábeis','Segundo a NBC TG 26 (R5) - APRESENTAÇÃO DAS DEMONSTRAÇÕES CONTÁBEIS, quando da elaboração de demonstrações contábeis, a administração deve avaliar a capacidade de a entidade continuar em operação no futuro previsível, o que significa que as demonstrações contábeis devem ser elaboradas no pressuposto da',null,'{"original": ["/cfc-2025-1/q15-1.png"]}','["continuidade, a menos que a administração tenha a intenção de liquidar a entidade ou cessar seus negócios, ou ainda não possua uma alternativa realista senão a descontinuidade de suas atividades.", "competência, sendo os itens reconhecidos como ativos, passivos, patrimônio líquido, receitas e despesas, inclusive para a demonstração de fluxo de caixa.", "materialidade e agregação, tendo a entidade que apresentar conjuntamente nas demonstrações contábeis cada classe material de itens semelhantes, aglutinando os de natureza ou função distinta mesmo que sejam materiais.", "compensação de valores, ativos e passivos ou receitas e despesas devem ser compensados, exceto quando permitido exclusivamente por norma."]'::jsonb,'A',null from public.exams where slug='cfc-2025-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,16,'Ciências Contábeis','Sobre a classificação e mensuração de ativos não circulantes mantidos para a venda, de acordo com a NBC TG 31 (R4) - ATIVO NÃO CIRCULANTE MANTIDO PARA VENDA E OPERAÇÃO DESCONTINUADA, analise as seguintes afirmativas: I. Os ativos não circulantes mantidos para a venda, desde que satisfeitos os critérios de classificação, são realocados para o ativo circulante da entidade. II. A classificação, a apresentação e a mensuração requeridas pela NBC TG 31 aplicáveis a ativo não circulante classificado como mantido para venda também se aplicam a ativo não circulante que seja classificado como destinado a ser distribuído aos sócios na sua condição de proprietários. III. O ativo não circulante mantido para venda será mensurado pelo maior entre o seu valor contábil e o valor justo menos as despesas de venda. Está correto o que se afirma em',null,'{"original": ["/cfc-2025-1/q16-1.png"]}','["I, somente.", "I e II, somente.", "I, II e III.", "II, somente."]'::jsonb,'B',null from public.exams where slug='cfc-2025-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,17,'Ciências Contábeis','A NBC TG ESTRUTURA CONCEITUAL descreve uma série de conceitos utilizados para a elaboração de relatórios financeiros para fins gerais. Relacione cada elemento a seguir com sua correta definição segundo a Estrutura Conceitual. Elemento Definição I. Aumentos nos ativos, ou reduções nos passivos, que resultam em aumento no a. Despesa patrimônio líquido. b. Patrimônio Líquido II. Reduções nos ativos, ou aumentos nos passivos, que resultam em reduções no c. Receita patrimônio líquido. III. Participação residual nos ativos da entidade após a dedução de todos os seus passivos. Os elementos a, b e c correspondem, respectivamente, às definições',null,'{"original": ["/cfc-2025-1/q17-1.png"]}','["II – III – I.", "I – III – II.", "II – I – III.", "I – II – III. CONTABILIDADE GERAL"]'::jsonb,'A',null from public.exams where slug='cfc-2025-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,18,'Ciências Contábeis','De acordo com a NBC TG 25 (R2) - PROVISÕES, PASSIVOS CONTINGENTES E ATIVOS CONTINGENTES, provisão é um passivo de prazo incerto ou de valor incerto. Considere que a sociedade empresária Beta tenha recebido laudo de seu advogado sobre um provável pagamento de processo trabalhista, entretanto com mensuração ainda não confiável. Nesse caso, o seu reconhecimento nas demonstrações financeiras deve ser',null,'{"original": ["/cfc-2025-1/q18-1.png"]}','["como apropriação por competência no balanço patrimonial.", "como provisão trabalhista no balanço patrimonial.", "não realizar reconhecimento de provisão trabalhista no balanço patrimonial e não divulgar em nota explicativa.", "não realizar reconhecimento de provisão trabalhista no balanço patrimonial, mas divulgar em nota explicativa como passivo contingente."]'::jsonb,'D',null from public.exams where slug='cfc-2025-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,19,'Ciências Contábeis','De acordo com a NBC TG 09 (R1) - DEMONSTRAÇÃO DO VALOR ADICIONADO, a referida Demonstração (DVA) está relacionada com informações econômicas e com a comunicação de elementos ambientais, sociais e de governança (ASG), e tem por finalidade evidenciar a riqueza criada pela entidade e sua distribuição, durante determinado período. Nesse sentido, considerando que a sociedade empresária “B” possui reversão de perdas estimadas com créditos de liquidação duvidosa, essa informação deve ser apresentada, em sua DVA, do seguinte modo:',null,'{"original": ["/cfc-2025-1/q19-1.png"]}','["em remuneração de capitais próprios, na segunda parte da DVA.", "em remuneração de capitais de terceiros, na segunda parte da DVA.", "em valor adicionado recebido em transferência, na primeira parte da DVA.", "em riqueza criada pela própria entidade, na primeira parte da DVA."]'::jsonb,'D',null from public.exams where slug='cfc-2025-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,20,'Ciências Contábeis','A Demonstração do Valor Adicionado proporciona aos usuários das demonstrações contábeis informações relativas à riqueza criada pela entidade em determinado período e à forma como tais riquezas foram distribuídas. Na distribuição do valor adicionado, o total de “Remuneração de capitais próprios” deve ser igual',null,'{"original": ["/cfc-2025-1/q20-1.png"]}','["às reservas de lucro reportadas no Balanço Patrimonial.", "ao pagamento de dividendos reportado na Demonstração dos Fluxos de Caixa.", "ao resultado líquido do exercício reportado na Demonstração do Resultado do Período.", "à distribuição de dividendos reportada na Demonstração das Mutações do Patrimônio Líquido."]'::jsonb,'C',null from public.exams where slug='cfc-2025-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,21,'Ciências Contábeis','Uma loja que vende produtos de escritório apresentava os seguintes saldos em 31/12/2023: • Custo da mercadoria vendida (inclui os valores dos impostos recuperáveis): R$ 80.000,00 • Despesa de depreciação dos ativos imobilizados: R$ 15.000,00 • Perdas estimadas com crédito de liquidação duvidosa: R$ 6.000,00 • Perdas por desvalorização dos ativos imobilizados: R$ 10.000,00 • Receita de contrato com clientes: R$ 200.000,00 Assinale a opção que indica o saldo do valor adicionado líquido produzido pela loja, apresentado em sua Demonstração do Valor Adicionado em 31/12/2023.',null,'{"original": ["/cfc-2025-1/q21-1.png"]}','["R$ 89.000,00.", "R$ 114.000,00.", "R$ 104.000,00.", "R$ 194.000,00."]'::jsonb,'A',null from public.exams where slug='cfc-2025-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,22,'Ciências Contábeis','De acordo com a NBC TG 25 (R2) - PROVISÕES, PASSIVOS CONTINGENTES E ATIVOS CONTINGENTES, a entidade deve divulgar, em notas explicativas, para cada classe de passivo contingente na data do balanço, uma breve descrição da natureza do passivo contingente, a menos que a possibilidade de ocorrer qualquer desembolso na liquidação seja',null,'{"original": ["/cfc-2025-1/q22-1.png"]}','["remota.", "possível.", "provável.", "possível e provável."]'::jsonb,'A',null from public.exams where slug='cfc-2025-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,23,'Ciências Contábeis','A sociedade empresária Solar administra a carreira de influenciadores digitais. As empresas interessadas em divulgar o seu produto ou serviço por meio dos influenciadores devem pagar para a Solar R$ 20.000,00 por um pacote que consiste em oito inserções em redes socias, sendo quatro ao mês. Em 01/05/2024, a Cia Yellow assinou contrato e pagou, à vista, R$ 20.000,00 para a Cia Solar. Foram realizadas quatro inserções em junho e quatro em julho. A Cia Yellow estimou que, por conta da divulgação, o seu faturamento aumentou em R$ 15.000,00 em agosto e em R$ 18.000,00 em setembro. De acordo com o Regime de Competência, a despesa com a divulgação deve ser reconhecida pela Cia Yellow do seguinte modo:',null,'{"original": ["/cfc-2025-1/q23-1.png"]}','["R$ 20.000,00 em maio.", "R$ 10.000,00 em junho e R$ 10.000,00 em julho.", "R$ 10.000,00 em agosto e R$ 10.000,00 em setembro.", "R$ 5.000,00 em cada um dos meses de junho a setembro."]'::jsonb,'B',null from public.exams where slug='cfc-2025-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,24,'Ciências Contábeis','Em 01/09/2024, uma sociedade empresária localizada em Belo Horizonte adquiriu aparelhos de informática de Manaus por R$ 40.000,00. O frete para a entrega por caminhão era de R$ 2.000,00. No entanto, para receber os aparelhos mais rápido, a sociedade empresária solicitou a entrega por avião e pagou o valor de R$ 5.500,00 pelo frete. A instalação dos aparelhos no escritório custou R$ 1.000,00. Ainda, foram gastos R$ 2.000,00 com testes para verificar se os aparelhos estavam funcionando corretamente. O valor dos aparelhos de informática a serem registrados no ativo imobilizado da sociedade empresária é de',null,'{"original": ["/cfc-2025-1/q24-1.png"]}','["R$ 43.000,00.", "R$ 45.000,00.", "R$ 46.500,00.", "R$ 48.500,00."]'::jsonb,'D',null from public.exams where slug='cfc-2025-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,25,'Ciências Contábeis','Em janeiro de 2025, um artista, que possui uma empresa, estava em um evento estratégico em um resort na Bahia. Ao voltar da viagem, descobriu que um influenciador digital, que também estava no evento, divulgou fotos e vídeos do artista em redes sociais. A empresa do artista entrou na justiça por quebra de privacidade contra o resort e contra o influenciador, pedindo, respectivamente, R$ 10.000,00 e R$ 15.000,00. Os advogados da empresa do artista julgaram que as chances de ganho das causas eram, respectivamente, remota e possível. Com base no julgamento dos advogados, a empresa deve apresentar, em suas demonstrações contábeis, um ativo contingente',null,'{"original": ["/cfc-2025-1/q25-1.png"]}','["igual a zero.", "de R$ 10.000,00.", "de R$ 15.000,00.", "de R$ 25.000,00."]'::jsonb,'A',null from public.exams where slug='cfc-2025-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,26,'Ciências Contábeis','A Cia Lua atua no setor de comércio de relógios e tem 20 empregados. Todos os anos, na primeira semana de janeiro, a empresa contrata uma equipe de médicos para ir ao escritório realizar exames de rotina em seus empregados. Em janeiro de 2025, os gastos com os médicos foram de R$ 6.000,00. Do valor, 20% são pagos pelos empregados, enquanto o restante é pago pela empresa. O impacto do atendimento médico na Demonstração do Resultado da Cia Lua em janeiro de 2025, de acordo com o Regime de Competência, foi de',null,'{"original": ["/cfc-2025-1/q26-1.png"]}','["-R$ 400,00.", "-R$ 500,00.", "-R$ 4.800,00.", "-R$ 6.000,00."]'::jsonb,'C',null from public.exams where slug='cfc-2025-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,27,'Ciências Contábeis','Em fevereiro de 2025, um hotel adquiriu um televisor de 98 polegadas para que os seus hospedes assistissem a cerimônia do Oscar, em março. O preço do televisor era de R$ 40.000,00. Na data da compra foi acordado com o fornecedor que o pagamento seria realizado por Pix e, em decorrência, o hotel obteve uma redução de 5% sobre o preço original. Assinale a opção que indica a contrapartida da diminuição de R$ 38.000,00 na conta “Disponibilidades”, nas demonstrações contábeis do hotel.',null,'{"original": ["/cfc-2025-1/q27-1.png"]}','["Ativo imobilizado de R$ 38.000,00.", "Ativo imobilizado de R$ 40.000,00 e receita financeira de R$ 2.000,00.", "Ativo imobilizado de R$ 40.000,00 e outras receitas de R$ 2.000,00.", "Ativo imobilizado de R$ 40.000,00 e retificação do ativo imobilizado de R$ 2.000,00."]'::jsonb,'A',null from public.exams where slug='cfc-2025-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,28,'Ciências Contábeis','Uma empresa de doces e bolos possui em 31/12/X0 os seguintes saldos em seu Balanço Patrimonial: • Caixa e equivalentes de caixa: R$ 100.000,00; • Empréstimos a pagar de curto prazo: R$ 250.000,00; • Financiamentos a pagar de longo prazo: R$ 330.000,00; • Imobilizado: R$ 450.000,00; • Intangível: R$ 320.000,00; • Estoques: R$ 250.000,00; • Capital Social: R$ 540.000,00. Com base nesses saldos, o valor do ativo não circulante da empresa é',null,'{"original": ["/cfc-2025-1/q28-1.png"]}','["R$ 770.000,00.", "R$ 350.000,00.", "R$ 1.020.000,00.", "R$ 450.000,00."]'::jsonb,'A',null from public.exams where slug='cfc-2025-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,29,'Ciências Contábeis','A empresa ABC S.A. comprou materiais, em agosto de X1, com a finalidade de utilizá-los em suas atividades. O pagamento foi realizado em novembro de X1, e os materiais foram utilizados na prestação de serviços em setembro de X1. Esses materiais devem ser reconhecidos como despesa no mês de',null,'{"original": ["/cfc-2025-1/q29-1.png"]}','["novembro de X1.", "setembro de X1.", "agosto de X1.", "dezembro de X1."]'::jsonb,'B',null from public.exams where slug='cfc-2025-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,30,'Ciências Contábeis','Relacione as contas contábeis do balanço patrimonial apresentadas a seguir com seus respectivas grupos contábeis. 1. Empréstimos a pagar após 12 meses. 2. Contas a receber em 5 meses. 3. Contas a pagar em 3 meses. 4. Imóveis para uso por 10 anos. ( ) Ativo Circulante. ( ) Ativo Não Circulante. ( ) Passivo Circulante. ( ) Passivo Não Circulante. A relação correta, na ordem apresentada, é',null,'{"original": ["/cfc-2025-1/q30-1.png"]}','["4 – 2 – 1 – 3.", "2 – 4 – 3 – 1.", "3 – 1 – 2 – 4.", "1 – 3 – 4 – 2."]'::jsonb,'B',null from public.exams where slug='cfc-2025-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,31,'Ciências Contábeis','Assinale a opção que contempla apenas componentes do Patrimônio Líquido, descritos na Lei nº 6.404/76 e alterações posteriores.',null,'{"original": ["/cfc-2025-1/q31-1.png"]}','["Capital Social – Investimentos – Ações em Tesouraria.", "Capital Social – Dividendos Obrigatórios a Pagar – Ajustes de Avaliação Patrimonial.", "Reservas de Capital – Reservas de Lucros – Ações em Tesouraria.", "Ajustes de Avaliação Patrimonial – Capital Social – Debêntures."]'::jsonb,'C',null from public.exams where slug='cfc-2025-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,32,'Ciências Contábeis','A companhia investidora Alfa S.A., obrigada legalmente a elaborar demonstrações financeiras consolidadas, possui a seguinte participação societária nas empresas: Investida % de participação de Alfa S.A. PL da investida em 31/12/2023 Kappa (controlada) 90 R$ 1.000.000,00 Sigma (controlada) 70 R$ 700.000,00 Zeta (coligada) 25 R$ 600.000,00 Delta (sem influência significativa) 15 R$ 900.000,00 Com base exclusivamente nas informações acima, o montante registrado na conta de participação de acionistas não controladores no balanço consolidado da investidora Alfa S.A. em 31/12/2023 deverá ser de',null,'{"original": ["/cfc-2025-1/q32-1.png"]}','["R$ 100.000,00.", "R$ 310.000,00.", "R$ 760.000,00.", "R$ 1.525.000,00."]'::jsonb,'B',null from public.exams where slug='cfc-2025-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,33,'Ciências Contábeis','Uma empresa adquiriu uma máquina e registrou na contabilidade os seguintes dispêndios: • Preço de aquisição: R$ 500.000,00; • Imposto de importação: R$ 50.000,00 (não recuperável); • Preparação do local: R$ 100.000,00; • Custo com materiais consumido na realização de testes de funcionamento: R$ 50.000,00; • Honorários dos técnicos que realizaram os testes: R$ 60.000,00; • Vida útil estimada: 10 anos; • Valor residual: R$ 100.000,00. De acordo com a NBC TG 27 (R4) - ATIVO IMOBILIZADO, o custo da máquina, ou seja, o valor contábil de registro inicial desse imobilizado, será de',null,'{"original": ["/cfc-2025-1/q33-1.png"]}','["R$ 500.000,00.", "R$ 550.000,00.", "R$ 650.000,00.", "R$ 760.000,00."]'::jsonb,'D',null from public.exams where slug='cfc-2025-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,34,'Ciências Contábeis','Uma empresa adquiriu uma máquina em 01/01/2020 pelo custo total de R$ 240.000,00. No registro inicial da máquina no imobilizado, a empresa estimou a vida útil da máquina em 8 anos, sem valor residual. Na data da aquisição, a empresa iniciou a depreciação pelo método linear. Em 31/12/2024, a empresa reavaliou a vida útil para 10 anos, aumentando em 2 anos a vida útil inicialmente estimada. Além disso, verificou que o valor residual da máquina passou a ser de R$ 40.000,00. Com base exclusivamente nos dados acima apresentados, o valor anual da despesa de depreciação a ser contabilizada a partir das alterações ocorridas em 31/12/2024 deve ser de',null,'{"original": ["/cfc-2025-1/q34-1.png"]}','["R$ 40.000,00.", "R$ 30.000,00.", "R$ 18.000,00.", "R$ 10.000,00. CONTABILIDADE DE CUSTOS"]'::jsonb,'D',null from public.exams where slug='cfc-2025-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,35,'Ciências Contábeis','A Indústria Cadeiras Maceió Ltda. produz e comercializa cadeiras de escritório. No mês de setembro de X4, a empresa produziu 30.000 cadeiras e não possuía estoque inicial. No mês, vendeu 24.000 unidades a um preço unitário de R$ 100,00. Os custos variáveis totais, incluindo matéria-prima, mão de obra direta e outros custos variáveis, somaram R$ 1.800.000,00. Os custos fixos, compostos principalmente por aluguel da fábrica, depreciação do maquinário e salários fixos dos supervisores da produção, totalizaram R$ 200.000,00. As despesas fixas, como gastos com administração e vendas, somaram R$ 100.000,00. Com base nessas informações, o lucro obtido com as vendas, aplicando o método de custeio variável, foi de',null,'{"original": ["/cfc-2025-1/q35-1.png"]}','["R$ 660.000,00.", "R$ 960.000,00.", "R$ 700.000,00.", "R$ 300.000,00."]'::jsonb,'A',null from public.exams where slug='cfc-2025-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,36,'Ciências Contábeis','Em janeiro de 2024, uma fábrica que produz bolas de futebol incorreu nos seguintes gastos: aluguel do imóvel e das máquinas: R$ 30.000,00; embalagens indispensáveis ao produto final: R$ 2.000,00; matéria-prima: R$ 10.000,00; seguro do imóvel: R$ 5.000,00. Assinale a opção que indica os custos fixos da fábrica no mês.',null,'{"original": ["/cfc-2025-1/q36-1.png"]}','["R$ 5.000,00.", "R$ 30.000,00.", "R$ 35.000,00.", "R$ 45.000,00."]'::jsonb,'C',null from public.exams where slug='cfc-2025-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,37,'Ciências Contábeis','Leia o fragmento a seguir: “Departamento é a unidade _____ administrativa para a Contabilidade de Custos, representada, na maioria dos casos, por pessoas e máquinas, em que se desenvolvem atividades _____.” Assinale a opção cujos itens completam corretamente as lacunas do fragmento.',null,'{"original": ["/cfc-2025-1/q37-1.png"]}','["padrão – heterogêneas", "mínima – homogêneas", "máxima – complementares", "padrão – complementares"]'::jsonb,'B',null from public.exams where slug='cfc-2025-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,38,'Ciências Contábeis','Gasto pode ser definido como o sacrifício financeiro necessário para obter um produto ou serviço, representado pela entrega ou promessa de entrega de ativos. Assim, custos, despesas, investimentos e desembolsos são tipos de gastos. Em relação ao tema, analise as afirmativas a seguir. I. Custo é um gasto diretamente relacionado a um bem ou serviço utilizado na produção de outros bens e serviços. II. Despesa é um gasto com bens ou serviços consumidos direta ou indiretamente para obtenção de receitas. III. Investimento é um gasto que se tornou um item do patrimônio líquido em função da expectativa de geração futura de caixa para a entidade ou em função de sua vida útil. IV. Desembolso é um gasto que ocorre quando bens ou serviços são consumidos de forma anormal e/ou involuntária que afetam diretamente o resultado da entidade. Estão corretas as afirmativas',null,'{"original": ["/cfc-2025-1/q38-1.png"]}','["III e IV, apenas.", "I, II e III, apenas.", "I e II, apenas.", "II, III e IV, apenas. CONTABILIDADE GERENCIAL"]'::jsonb,'C',null from public.exams where slug='cfc-2025-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,39,'Ciências Contábeis','Em 01/01/2024, uma loja de teclados apresentava os seguintes saldos em seu balanço patrimonial: • Disponibilidades: R$ 60.000,00; • Estoque: R$ 240.000,00; • Patrimônio Líquido: R$ 300.000,00. O estoque era composto por 400 unidades de teclado, sendo que cada uma era vendida por R$ 1.000,00. No primeiro semestre de 2024, os gastos fixos, considerando a loja e o escritório, foram os seguintes: • Aluguel: R$ 36.000,00; • Depreciação: R$ 30.000,00; • Salários: R$ 60.000,00. Além disso, foi paga, antecipadamente, uma despesa de R$ 4.000,00 relacionada ao segundo semestre do ano. O ponto de equilíbrio contábil da loja, em unidades, no primeiro semestre de 2024, foi de',null,'{"original": ["/cfc-2025-1/q39-1.png"]}','["240.", "300.", "315.", "375."]'::jsonb,'C',null from public.exams where slug='cfc-2025-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,40,'Ciências Contábeis','Acerca do Modelo de Determinação do Preço de Transferência, avalie as afirmativas a seguir. I. No Modelo de Preço de Transferência Baseado em Custo Total Realizado (Full Cost), o bem/serviço é transferido pelo valor resultante do somatório dos custos totais incorridos (fixos e variáveis) dividido pelo volume de produção de um determinado período (custeio por absorção). II. No Modelo de Preço de Transferência Baseado em Negociação entre os Gestores, o bem/serviço é transferido pelo preço vigente no mercado, que pode ser um preço médio. III. No Modelo de Preço de Transferência Baseado em Custo de Oportunidade, o preço do bem/serviço transferido estrutura- se a partir da premissa de que deveria refletir o valor do benefício possível de ser auferido na melhor alternativa econômica de obtenção dos insumos demandados. Está correto o que se afirma em',null,'{"original": ["/cfc-2025-1/q40-1.png"]}','["I, apenas.", "I e II, apenas.", "I e III, apenas.", "I, II e III."]'::jsonb,'C',null from public.exams where slug='cfc-2025-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,41,'Ciências Contábeis','Analise as contas do Balanço Patrimonial a seguir: ATIVO 2023 PASSIVO 2023 Caixa R$ 5.000,00 Fornecedores R$ 15.000,00 Aplicações financeiras R$ 10.000,00 Impostos a pagar R$ 5.000,00 Contas a receber R$ 15.000,00 Empréstimos de curto prazo R$ 10.000,00 Estoques R$ 30.000,00 Empréstimos de longo prazo R$ 20.000,00 Imobilizado R$ 10.000,00 Patrimônio líquido R$ 80.000,00 Intangível R$ 50.000,00 Investimentos R$ 10.000,00 TOTAL R$ 130.000,00 TOTAL R$ 130.000,00 O Índice de Liquidez Seca e o Índice de Liquidez Corrente são, respectivamente, iguais a',null,'{"original": ["/cfc-2025-1/q41-1.png"]}','["2,00 e 1,00.", "1,00 e 2,00.", "1,00 e 2,60.", "2,00 e 0,75. CONTABILIDADE APLICADA AO SETOR PÚBLICO"]'::jsonb,'B',null from public.exams where slug='cfc-2025-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,42,'Ciências Contábeis','A Lei Orçamentária Anual de cada ente federado deverá conter todas as receitas e despesas de todos os Poderes, órgãos, entidades, fundos e fundações instituídas e mantidas pelo Poder Público. Esse princípio orçamentário é denominado',null,'{"original": ["/cfc-2025-1/q42-1.png"]}','["Unidade.", "Universalidade.", "Exclusividade.", "Orçamento Bruto."]'::jsonb,'B',null from public.exams where slug='cfc-2025-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,43,'Ciências Contábeis','De acordo com a NBC TSP ESTRUTURA CONCEITUAL - ESTRUTURA CONCEITUAL PARA ELABORAÇÃO E DIVULGAÇÃO DE INFORMAÇÃO CONTÁBIL DE PROPÓSITO GERAL PELAS ENTIDADES DO SETOR PÚBLICO, as informações financeiras e não financeiras são relevantes quando',null,'{"original": ["/cfc-2025-1/q43-1.png"]}','["permitem que os usuários compreendam o seu significado.", "retratam a substância da transação, a qual pode não corresponder, necessariamente, à sua forma jurídica.", "são capazes de influenciar significativamente o cumprimento dos objetivos da elaboração e da divulgação da informação contábil.", "estão disponíveis aos usuários a tempo de serem úteis para fins de prestação de contas, responsabilização e tomada de decisão."]'::jsonb,'C',null from public.exams where slug='cfc-2025-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,44,'Ciências Contábeis','Com relação aos usuários dos Relatórios Contábeis de Propósito Geral das Entidades do Setor Público (RCPGs), avalie as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) Os RCPGs devem ser elaborados e divulgados, principalmente, para atender às necessidades de informações dos usuários dos serviços e dos provedores de recursos, quando estes detêm a prerrogativa de exigir que a entidade do setor público divulgue as informações que atendam às suas necessidades específicas. ( ) Os membros do Poder Legislativo são também usuários primários dos RCPGs e utilizam extensiva e continuamente os relatórios enquanto atuam como representantes dos interesses dos usuários de serviços e dos provedores de recursos. ( ) Alguns usuários dos serviços e alguns provedores de recursos que dependem dos RCPGs para obter informações que eles necessitam para os propósitos de prestação de contas e responsabilização e tomada de decisão podem não ser cidadãos, como, agências bilaterais ou multilaterais. De acordo com a NBC TSP ESTRUTURA CONCEITUAL- ESTRUTURA CONCEITUAL PARA ELABORAÇÃO E DIVULGAÇÃO DE INFORMAÇÃO CONTÁBIL DE PROPÓSITO GERAL PELAS ENTIDADES DO SETOR PÚBLICO as afirmativas são, respectivamente,',null,'{"original": ["/cfc-2025-1/q44-1.png"]}','["V – F – F.", "V – F – V.", "F – V – V.", "V – V – F. CONTROLADORIA"]'::jsonb,'C',null from public.exams where slug='cfc-2025-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,45,'Ciências Contábeis','Em 2022, uma entidade tinha o seu desempenho financeiro analisado com base no Retorno sobre o Investimento. Em 2023, a administração da entidade determinou que o seu desempenho passasse a ser avaliado com base no EVA (Valor Econômico Agregado). Uma vantagem dessa substituição é a incorporação, na avaliação,',null,'{"original": ["/cfc-2025-1/q45-1.png"]}','["do custo de oportunidade.", "das receitas operacionais.", "das despesas operacionais.", "das receitas financeiras."]'::jsonb,'A',null from public.exams where slug='cfc-2025-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,46,'Ciências Contábeis','A Administração de uma empresa, na elaboração de seu plano estratégico, deve, na medida do possível, observar alguns aspectos de formalidade necessários dado a sua relevância e seu impacto nas operações da empresa. A respeito desse tema, avalie as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) O Plano Estratégico deve ser executado pela Controladoria sob o comando da alta administração da empresa. ( ) Uma vez elaborado e aprovado, o Plano Estratégico não deve ser alterado ou ajustado. ( ) Planejamento Estratégico é a atividade que se ocupa da implementação do Plano Estratégico e assegura que os recursos necessários foram obtidos e também que estão sendo usados de maneira eficiente. ( ) A elaboração de um Planejamento Estratégico deve levar em consideração que todas as decisões são interdependentes, sejam elas simples ou complexas. Assim, um dos principais desafios dessa atividade é um ajustamento dessa cadeia sistêmica de decisões e a avaliação de suas consequências. As afirmativas são, respectivamente,',null,'{"original": ["/cfc-2025-1/q46-1.png"]}','["F – V – V – F.", "F – V – F – V.", "V – F – F – V.", "V – F – V – F. AUDITORIA CONTÁBIL"]'::jsonb,'C',null from public.exams where slug='cfc-2025-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,47,'Ciências Contábeis','Uma empresa de auditoria independente precisou contratar o trabalho de um especialista na área de Tecnologia da Informação. Após receber as conclusões do especialista, foi constatado que esse trabalho era adequado para fins da auditoria. Com base na NBC TA 620 – UTILIZAÇÃO DO TRABALHO DE ESPECIALISTAS, assinale a afirmativa correta acerca da responsabilidade do auditor ao emitir a sua opinião.',null,'{"original": ["/cfc-2025-1/q47-1.png"]}','["O auditor tem sua responsabilidade dividida com o especialista em todo o trabalho.", "O auditor é o único responsável por expressar opinião de auditoria, e essa responsabilidade não é reduzida pelo trabalho de especialista contratado pelo auditor.", "O auditor é responsável pela parte contábil, e o especialista, pelo trabalho que fez.", "O auditor, modificando sua opinião em virtude do trabalho do especialista, não terá nenhuma responsabilidade, sendo a responsabilidade transferida ao especialista."]'::jsonb,'B',null from public.exams where slug='cfc-2025-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,48,'Ciências Contábeis','No exercício de 2024, uma sociedade empresária foi incluída em um Plano de Refinanciamento de Impostos. O fato foi apropriadamente divulgado nas demonstrações contábeis. Mesmo sendo divulgado o Plano de Refinanciamento de Impostos, o auditor julgou que o assunto é de importância fundamental para o entendimento pelos usuários das demonstrações contábeis. Assim, o auditor independente incluirá, em seu relatório,',null,'{"original": ["/cfc-2025-1/q48-1.png", "/cfc-2025-1/q48-2.png"]}','["uma ressalva.", "um fato relevante.", "um parágrafo de ênfase.", "um parágrafo de outros assuntos. PERÍCIA CONTÁBIL"]'::jsonb,'C',null from public.exams where slug='cfc-2025-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,49,'Ciências Contábeis','Julgue as afirmativas a seguir, com base na NBC TP 01 (R1) - PERÍCIA CONTÁBIL. I. Concluídos os trabalhos periciais, o perito nomeado deve apresentar laudo pericial contábil, e o assistente técnico deve oferecer seu parecer pericial contábil, obedecendo aos respectivos prazos legais e/ou contratuais. II. O assistente técnico não pode validar o laudo pericial quando o documento tiver sido elaborado por leigo ou profissional de outra área, devendo, nesse caso, oferecer o parecer pericial contábil sobre a matéria periciada. III. Mesmo quando assinado em conjunto por peritos, a responsabilidade acerca do laudo pericial contábil é exclusiva do perito nomeado, não sendo passível a assunção de responsabilidade solidária pelos demais peritos assinantes no documento. IV. As respostas aos quesitos devem ser objetivas, completas e não lacônicas. Estão corretas as afirmativas',null,'{"original": ["/cfc-2025-1/q49-1.png"]}','["III e IV, apenas.", "I e II, apenas.", "I e III, apenas.", "II e IV, apenas."]'::jsonb,'D',null from public.exams where slug='cfc-2025-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,50,'Ciências Contábeis','A Norma Brasileira de Contabilidade Profissional – Perito (NBC PP 01) estabelece as diretrizes e os requisitos para a atuação dos contadores como peritos, incluindo qualificações, deveres, responsabilidades, normas de conduta e as situações que podem acarretar impedimento ou suspeição. Analise as afirmativas a seguir, com base na NBC PP 01, e assinale (V) para a afirmativa verdadeira e (F) para a falsa. ( ) Em casos de impedimento ou suspeição, o perito contábil tem a opção de continuar no caso desde que obtenha o consentimento expresso de todas as partes envolvidas e da autoridade competente. ( ) A NBC PP 01 permite que o perito utilize documentos externos aos autos processuais como elementos de prova, desde que previamente acordado com as partes e autorizado pelo juiz ou autoridade competente. ( ) O perito contábil deve elaborar a proposta de honorários periciais considerando não apenas os custos e o tempo necessário para a execução dos trabalhos, mas também levando em conta a relevância e o risco envolvidos no objeto da perícia. As afirmativas são, respectivamente,',null,'{"original": ["/cfc-2025-1/q50-1.png"]}','["F – F – V.", "V – F – F.", "F – V – F.", "V – V – V."]'::jsonb,'A',null from public.exams where slug='cfc-2025-1' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
